CREATE OR REPLACE FUNCTION public.save_spreadsheet_formulas_v1(p_actor uuid, p_table text, p_changes jsonb)
 RETURNS SETOF spreadsheet_cell_formulas
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE change jsonb; current_version integer; changed public.spreadsheet_cell_formulas; ids uuid[]='{}'; bad_graph boolean;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=p_actor AND upper(role) IN ('ADMIN','STAFF')) THEN RAISE EXCEPTION 'Formula access denied' USING ERRCODE='42501'; END IF;
 IF p_table NOT IN ('trips','report:combined','report:dispatch-monitoring','report:dispatch','report:trip-booking','report:store-calling','report:pod-status','report:pod-drive-files','report:trip-exceptions','transmittal-tracker','operations')
 OR jsonb_typeof(p_changes)<>'array' OR jsonb_array_length(p_changes) NOT BETWEEN 1 AND 50 THEN RAISE EXCEPTION 'Invalid formula batch' USING ERRCODE='22023'; END IF;
 PERFORM pg_advisory_xact_lock(hashtext('spreadsheet-formula:'||p_table));
 IF (SELECT count(*) FROM jsonb_array_elements(p_changes))<>(SELECT count(DISTINCT (c->>'row_identity',c->>'column_key')) FROM jsonb_array_elements(p_changes)c) THEN RAISE EXCEPTION 'Duplicate formula target' USING ERRCODE='22023'; END IF;
 FOR change IN SELECT value FROM jsonb_array_elements(p_changes) ORDER BY value->>'row_identity',value->>'column_key' LOOP
  SELECT version INTO current_version FROM public.spreadsheet_cell_formulas WHERE table_key=p_table AND row_identity=change->>'row_identity' AND column_key=change->>'column_key' FOR UPDATE;
  IF COALESCE(current_version,0)<>(change->>'expected_version')::integer THEN RAISE EXCEPTION 'Formula version conflict' USING ERRCODE='40001'; END IF;
  INSERT INTO public.spreadsheet_cell_formulas(table_key,row_identity,column_key,formula_expression,reference_bindings,is_deleted,created_by,updated_by)
  VALUES(p_table,change->>'row_identity',change->>'column_key',change->>'expression',COALESCE(change->'references','{}'::jsonb),change->>'expression' IS NULL,p_actor,p_actor)
  ON CONFLICT(table_key,row_identity,column_key) DO UPDATE SET formula_expression=EXCLUDED.formula_expression,reference_bindings=EXCLUDED.reference_bindings,is_deleted=EXCLUDED.is_deleted,version=spreadsheet_cell_formulas.version+1,updated_by=p_actor,updated_at=now()
  RETURNING * INTO changed;
  ids=array_append(ids,changed.id);
 END LOOP;
 -- Serialized graph validation includes the complete resulting batch, not a stale preview.
 WITH RECURSIVE edges AS (
  SELECT f.id a,g.id b FROM public.spreadsheet_cell_formulas f CROSS JOIN LATERAL jsonb_each(f.reference_bindings) r, public.spreadsheet_cell_formulas g
  WHERE g.table_key=f.table_key AND g.row_identity=r.value->>'rowId' AND g.column_key=r.value->>'columnId' AND NOT g.is_deleted AND f.table_key=p_table AND NOT f.is_deleted
 ), walk AS (
  SELECT a,b FROM edges
  UNION SELECT w.a,e.b FROM walk w JOIN edges e ON e.a=w.b
 ) SELECT EXISTS(SELECT 1 FROM walk WHERE a=b) INTO bad_graph;
 IF bad_graph THEN RAISE EXCEPTION 'Circular formula dependencies' USING ERRCODE='23514'; END IF;
 RETURN QUERY SELECT * FROM public.spreadsheet_cell_formulas WHERE id=ANY(ids);
END $function$
CREATE OR REPLACE FUNCTION public.generate_trip_reference()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  prefix text;
  next_number bigint;
BEGIN
  -- Assign on insert under a date-specific transaction lock so concurrent
  -- creators receive different references even if their previews matched.
  prefix := 'TRIP' || to_char(coalesce(NEW.loading_date::date, (now() AT TIME ZONE 'Asia/Manila')::date), 'YYMMDD');
  PERFORM pg_advisory_xact_lock(hashtextextended(prefix, 0));
  SELECT coalesce(max(substring(trip_reference FROM '^TRIP[0-9]{6}-([0-9]+)$')::bigint), 0) + 1
    INTO next_number FROM public.trips WHERE trip_reference LIKE prefix || '-%';
  NEW.trip_reference := prefix || '-' || next_number::text;
  RETURN NEW;
END;
$function$
CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$function$
CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$
CREATE OR REPLACE FUNCTION public.check_offload_receipt_capacity_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  IF NEW.offload_id IS NULL THEN RETURN NEW; END IF;
  IF TG_OP='UPDATE' AND OLD.offload_id IS NOT DISTINCT FROM NEW.offload_id THEN RETURN NEW; END IF;
  PERFORM id FROM public.offloads WHERE id=NEW.offload_id FOR UPDATE;
  IF (SELECT count(*) FROM public.report_receipts WHERE offload_id=NEW.offload_id AND id<>NEW.id)>=5 THEN
    RAISE EXCEPTION 'An Offload supports at most five images' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END;
$function$
CREATE OR REPLACE FUNCTION public.tracking_assignment_v1(p_id uuid, p_lock boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE a public.trip_truck_assignments%ROWTYPE; d public.drivers%ROWTYPE; t public.trips%ROWTYPE;
BEGIN
 IF p_lock THEN SELECT * INTO a FROM public.trip_truck_assignments WHERE id=p_id FOR UPDATE;
 ELSE SELECT * INTO a FROM public.trip_truck_assignments WHERE id=p_id; END IF;
 IF NOT FOUND THEN RETURN NULL; END IF;
 IF p_lock THEN
  SELECT * INTO d FROM public.drivers WHERE id=a.driver_id FOR SHARE;
  -- Parent row lock also blocks FK-checked new stop inserts until this context
  -- decision completes, preventing a phantom destination during finalization.
  SELECT * INTO t FROM public.trips WHERE id=a.trip_id FOR UPDATE;
 ELSE
  SELECT * INTO d FROM public.drivers WHERE id=a.driver_id;
  SELECT * INTO t FROM public.trips WHERE id=a.trip_id;
 END IF;
 RETURN jsonb_build_object('id',a.id,'tripId',a.trip_id,'profileId',d.profile_id,'revision',a.collaboration_version,
  'active',a.unassigned_at IS NULL AND t.archived_at IS NULL AND t.status NOT IN ('COMPLETED','CANCELLED') AND d.profile_id IS NOT NULL);
END $function$
CREATE OR REPLACE FUNCTION public.tracking_write_v1(p_actor uuid, p_assignment uuid, p_revision bigint, p_session uuid, p_action text, p_lat double precision DEFAULT NULL::double precision, p_lng double precision DEFAULT NULL::double precision, p_accuracy double precision DEFAULT NULL::double precision, p_captured timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE a jsonb; previous public.trip_tracking_locations%ROWTYPE;
BEGIN
 IF NOT EXISTS(SELECT FROM public.profiles WHERE id=p_actor AND role='TRUCKER' FOR SHARE) OR p_session IS NULL THEN
  RAISE EXCEPTION 'Tracking requires the authenticated trucker.' USING ERRCODE='42501'; END IF;
 a:=public.tracking_assignment_v1(p_assignment,true);
 IF p_action='STOP' THEN
  UPDATE public.trip_tracking_locations SET enabled=false,disabled_at=clock_timestamp(),revision=revision+1
   WHERE assignment_id=p_assignment AND profile_id=p_actor AND tracking_session_id=p_session AND enabled;
  RETURN FOUND;
 END IF;
 IF a IS NULL OR NOT (a->>'active')::boolean OR (a->>'profileId')::uuid<>p_actor OR (a->>'revision')::bigint<>p_revision THEN
  RAISE EXCEPTION 'Assignment changed or is not available to this trucker.' USING ERRCODE='42501'; END IF;
 IF p_action='START' THEN
  INSERT INTO public.trip_tracking_locations(assignment_id,profile_id,tracking_session_id) VALUES(p_assignment,p_actor,p_session)
  ON CONFLICT(assignment_id) DO UPDATE SET profile_id=p_actor,tracking_session_id=p_session,enabled=true,
   consented_at=clock_timestamp(),disabled_at=NULL,latitude=NULL,longitude=NULL,accuracy_meters=NULL,captured_at=NULL,received_at=NULL,
   revision=public.trip_tracking_locations.revision+1;
  RETURN true;
 END IF;
 IF p_action<>'CAPTURE' OR p_lat IS NULL OR p_lng IS NULL OR p_accuracy IS NULL OR p_captured IS NULL
  OR NOT(p_lat BETWEEN -90 AND 90) OR NOT(p_lng BETWEEN -180 AND 180) OR NOT(p_accuracy>=0 AND p_accuracy<100000)
  OR p_captured<clock_timestamp()-interval '2 minutes' OR p_captured>clock_timestamp()+interval '2 minutes' THEN
  RAISE EXCEPTION 'Invalid or stale GPS capture.' USING ERRCODE='22023'; END IF;
 SELECT * INTO previous FROM public.trip_tracking_locations WHERE assignment_id=p_assignment FOR UPDATE;
 IF NOT FOUND OR NOT previous.enabled OR previous.profile_id<>p_actor OR previous.tracking_session_id<>p_session
  OR previous.captured_at>=p_captured THEN RETURN false; END IF;
 IF previous.received_at>clock_timestamp()-interval '5 seconds' THEN RAISE EXCEPTION 'GPS rate limit reached.' USING ERRCODE='54000'; END IF;
 UPDATE public.trip_tracking_locations SET latitude=p_lat,longitude=p_lng,accuracy_meters=p_accuracy,
  captured_at=p_captured,received_at=clock_timestamp(),revision=revision+1 WHERE assignment_id=p_assignment;
 RETURN true;
END $function$
CREATE OR REPLACE FUNCTION public.tracking_route_context_v1(p_assignment uuid, p_lock boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE a jsonb; points jsonb; origin jsonb; plate text; dispatch text;
BEGIN
 a:=public.tracking_assignment_v1(p_assignment,p_lock); IF a IS NULL THEN RETURN NULL; END IF;
 IF p_lock THEN
  PERFORM 1 FROM public.trip_stops WHERE trip_id=(a->>'tripId')::uuid ORDER BY id FOR SHARE;
  PERFORM 1 FROM public.customer_stores WHERE id IN (SELECT store_id FROM public.trip_stops WHERE trip_id=(a->>'tripId')::uuid) ORDER BY id FOR SHARE;
 END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',s.id,'name',coalesce(st.name,'Destination'),'latitude',st.latitude,'longitude',st.longitude)
  ORDER BY s.stop_sequence,s.id),'[]'::jsonb) INTO points FROM public.trip_stops s
  LEFT JOIN public.customer_stores st ON st.id=s.store_id
  WHERE s.trip_id=(a->>'tripId')::uuid AND s.archived_at IS NULL AND coalesce(s.delivery_status,'PENDING') NOT IN ('COMPLETED','DELIVERED','CANCELLED');
 SELECT jsonb_build_object('id','position','latitude',l.latitude,'longitude',l.longitude,'captured_at',l.captured_at,
  'accuracy_meters',l.accuracy_meters,'revision',l.revision) INTO origin FROM public.trip_tracking_locations l
  WHERE l.assignment_id=p_assignment AND l.profile_id=(a->>'profileId')::uuid AND l.enabled AND l.captured_at IS NOT NULL;
 SELECT tr.plate_number,t.dispatch_number INTO plate,dispatch FROM public.trip_truck_assignments ta
  JOIN public.trucks tr ON tr.id=ta.truck_id JOIN public.trips t ON t.id=ta.trip_id WHERE ta.id=p_assignment;
 RETURN a||jsonb_build_object('destinations',points,'origin',origin,'plate_number',plate,'dispatch_number',dispatch,
  'context_token',md5(jsonb_build_array(a,points)::text));
END $function$
CREATE OR REPLACE FUNCTION public.tracking_route_write_v1(p_assignment uuid, p_action text, p_token uuid, p_context text, p_fingerprint text, p_expected bigint DEFAULT 0, p_geometry jsonb DEFAULT NULL::jsonb, p_distance double precision DEFAULT NULL::double precision, p_duration double precision DEFAULT NULL::double precision, p_error text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE ctx jsonb; r public.trip_route_cache%ROWTYPE; used integer; minute_start timestamptz:=date_trunc('minute',clock_timestamp());
BEGIN
 ctx:=public.tracking_route_context_v1(p_assignment,true);
 IF p_action='CLAIM' THEN
  IF p_token IS NULL OR ctx IS NULL OR NOT (ctx->>'active')::boolean OR ctx->>'context_token' IS DISTINCT FROM p_context OR ctx->'origin'='null'::jsonb
   OR p_fingerprint !~ '^[a-f0-9]{64}$' THEN RETURN false; END IF;
  -- Company-wide provider budget shared by all Node replicas; metadata only.
  PERFORM pg_advisory_xact_lock(771004219);
  SELECT coalesce(sum(window_requests),0) INTO used FROM public.trip_route_cache WHERE request_window=minute_start;
  IF used>=30 THEN RETURN false; END IF;
  SELECT * INTO r FROM public.trip_route_cache WHERE assignment_id=p_assignment FOR UPDATE;
  IF FOUND AND (r.revision<>p_expected OR r.lease_expires_at>clock_timestamp() OR r.retry_after>clock_timestamp()) THEN RETURN false; END IF;
  IF NOT FOUND AND p_expected<>0 THEN RETURN false; END IF;
  INSERT INTO public.trip_route_cache(assignment_id,destination_fingerprint,lease_token,lease_expires_at,revision,directions_requests,request_window,window_requests)
   VALUES(p_assignment,p_fingerprint,p_token,clock_timestamp()+interval '1 minute',1,1,minute_start,1)
  ON CONFLICT(assignment_id) DO UPDATE SET lease_token=p_token,lease_expires_at=clock_timestamp()+interval '1 minute',
   revision=public.trip_route_cache.revision+1,directions_requests=public.trip_route_cache.directions_requests+1,
   request_window=minute_start,window_requests=CASE WHEN public.trip_route_cache.request_window=minute_start THEN public.trip_route_cache.window_requests+1 ELSE 1 END;
  RETURN true;
 END IF;
 SELECT * INTO r FROM public.trip_route_cache WHERE assignment_id=p_assignment FOR UPDATE;
 IF NOT FOUND OR r.lease_token IS DISTINCT FROM p_token THEN RETURN false; END IF;
 IF p_action='FAIL' THEN
  UPDATE public.trip_route_cache SET lease_token=NULL,lease_expires_at=NULL,
   retry_after=clock_timestamp()+CASE WHEN p_error='ROUTE_RATE_LIMITED' THEN interval '5 minutes' ELSE interval '1 minute' END,
   last_error_code=left(p_error,100),revision=revision+1 WHERE assignment_id=p_assignment; RETURN true;
 END IF;
 IF p_action<>'FINISH' OR ctx IS NULL OR NOT (ctx->>'active')::boolean OR ctx->>'context_token' IS DISTINCT FROM p_context
  OR r.lease_expires_at<clock_timestamp() THEN RETURN false; END IF;
 IF p_geometry IS NULL OR p_geometry->>'type' IS DISTINCT FROM 'LineString' OR jsonb_typeof(p_geometry->'coordinates') IS DISTINCT FROM 'array'
  OR jsonb_array_length(p_geometry->'coordinates') NOT BETWEEN 2 AND 20000 OR octet_length(p_geometry::text)>1048576
  OR p_distance IS NULL OR p_duration IS NULL OR NOT(p_distance BETWEEN 0 AND 1000000000 AND p_duration BETWEEN 0 AND 1000000000) THEN
  RAISE EXCEPTION 'Invalid road route.' USING ERRCODE='22023'; END IF;
 UPDATE public.trip_route_cache SET destination_fingerprint=p_fingerprint,route_geometry=p_geometry,distance_meters=p_distance,duration_seconds=p_duration,
  calculated_at=clock_timestamp(),next_routine_at=clock_timestamp()+interval '1 hour',lease_token=NULL,lease_expires_at=NULL,
  retry_after=NULL,last_error_code=NULL,revision=revision+1 WHERE assignment_id=p_assignment;
 RETURN true;
END $function$
CREATE OR REPLACE FUNCTION public.proposed_loading_unloading_validate_receipt_scope_v1()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_parent_id uuid;
  v_parent_trip uuid;
  v_parent_stop uuid;
  v_parent_found boolean;
  v_parent_count bigint;
  v_parent_table text;
BEGIN
  IF NEW.backload_id IS NOT NULL THEN
    v_parent_id := NEW.backload_id;
    v_parent_table := 'backloads';
  ELSIF NEW.offload_id IS NOT NULL THEN
    v_parent_id := NEW.offload_id;
    v_parent_table := 'offloads';
  ELSE
    RETURN NEW;
  END IF;

  EXECUTE format(
    'SELECT trip_id, trip_stop_id FROM public.%I WHERE id = $1 FOR UPDATE',
    v_parent_table
  ) INTO v_parent_trip, v_parent_stop USING v_parent_id;
  GET DIAGNOSTICS v_parent_count = ROW_COUNT;
  v_parent_found := v_parent_count > 0;
  IF NOT v_parent_found THEN
    RAISE EXCEPTION 'The referenced parent report does not exist' USING ERRCODE = '23503';
  END IF;
  -- Keep lock order consistent with the parent UPDATE triggers: row first,
  -- then advisory lock. Hash collisions only serialize unrelated parents.
  PERFORM pg_advisory_xact_lock(
    hashtextextended(v_parent_table || ':' || v_parent_id::text, 0)
  );
  IF v_parent_trip IS DISTINCT FROM NEW.trip_id THEN
    RAISE EXCEPTION 'Receipt trip_id must match its parent report' USING ERRCODE = '23514';
  END IF;
  IF v_parent_stop IS NOT NULL AND NEW.trip_stop_id IS DISTINCT FROM v_parent_stop THEN
    RAISE EXCEPTION 'Receipt stop must match the stop-scoped backload/offload report' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$
CREATE OR REPLACE FUNCTION public.proposed_loading_unloading_guard_parent_scope_v1()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_has_receipts boolean;
BEGIN
  IF NEW.trip_id IS NOT DISTINCT FROM OLD.trip_id
     AND to_jsonb(NEW) ->> 'trip_stop_id' IS NOT DISTINCT FROM to_jsonb(OLD) ->> 'trip_stop_id' THEN
    RETURN NEW;
  END IF;
  -- PostgreSQL has already locked this parent row for UPDATE before invoking
  -- the BEFORE trigger. Acquire the same advisory lock as receipt writes only
  -- after that row lock, then perform the receipt check as a separate query.
  PERFORM pg_advisory_xact_lock(
    hashtextextended(TG_TABLE_NAME || ':' || OLD.id::text, 0)
  );
  EXECUTE format(
    'SELECT EXISTS (SELECT 1 FROM public.report_receipts WHERE %I = $1)',
    TG_ARGV[0]
  ) INTO v_has_receipts USING OLD.id;
  IF v_has_receipts THEN
    RAISE EXCEPTION 'Cannot change a report trip/stop binding while receipts are attached' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$
CREATE OR REPLACE FUNCTION public.prune_tracking_v1()
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
 DELETE FROM public.trip_tracking_locations WHERE coalesce(disabled_at,received_at,consented_at)<now()-interval '24 hours';
 DELETE FROM public.trip_route_cache r WHERE coalesce(calculated_at,lease_expires_at,request_window)<now()-interval '7 days' AND NOT EXISTS
  (SELECT 1 FROM public.trip_truck_assignments a JOIN public.trips t ON t.id=a.trip_id
   WHERE a.id=r.assignment_id AND a.unassigned_at IS NULL AND t.archived_at IS NULL AND t.status NOT IN ('COMPLETED','CANCELLED'));
$function$
CREATE OR REPLACE FUNCTION public.planned_route_context_v1(p_assignment uuid, p_lock boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE a jsonb; t public.trips%ROWTYPE; w public.warehouses%ROWTYPE; origin jsonb; points jsonb;
BEGIN
 a:=public.tracking_assignment_v1(p_assignment,p_lock);
 IF a IS NULL THEN RETURN NULL; END IF;
 SELECT * INTO t FROM public.trips WHERE id=(a->>'tripId')::uuid;
 IF p_lock THEN
  PERFORM 1 FROM public.trip_stops WHERE trip_id=t.id ORDER BY id FOR SHARE;
  PERFORM 1 FROM public.customer_stores WHERE id IN(SELECT store_id FROM public.trip_stops WHERE trip_id=t.id) ORDER BY id FOR SHARE;
  SELECT * INTO w FROM public.warehouses WHERE id=t.warehouse_id FOR SHARE;
 ELSE SELECT * INTO w FROM public.warehouses WHERE id=t.warehouse_id; END IF;
 origin:=jsonb_build_object('id',w.id,'latitude',w.latitude,'longitude',w.longitude);
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',s.id,'latitude',st.latitude,'longitude',st.longitude,'stopSequence',s.stop_sequence)
  ORDER BY s.stop_sequence NULLS LAST,s.id),'[]'::jsonb) INTO points
 FROM public.trip_stops s LEFT JOIN public.customer_stores st ON st.id=s.store_id
 WHERE s.trip_id=t.id AND s.archived_at IS NULL;
 RETURN jsonb_build_object('id',p_assignment,'tripId',t.id,
  'active',t.archived_at IS NULL AND t.status NOT IN('COMPLETED','CANCELLED') AND EXISTS(SELECT FROM public.trip_truck_assignments WHERE id=p_assignment AND unassigned_at IS NULL),
  'origin',origin,'destinations',points,
  'context_token',md5(jsonb_build_array(a,t.warehouse_id,origin,points)::text));
END $function$
CREATE OR REPLACE FUNCTION public.convert_operations_report_v1(p_source_type text, p_source_id uuid, p_target_type text, p_actor_profile_id uuid, p_target_fields jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_source_table text;
  v_target_table text;
  v_source_receipt_col text;
  v_target_receipt_col text;
  v_source_row jsonb;
  v_source_stop jsonb;
  v_target_row jsonb;
  v_target_id uuid;
  v_trip_id uuid;
  v_stop_id uuid;
  v_items jsonb := '[]'::jsonb;
  v_receipts jsonb := '[]'::jsonb;
  v_snapshot jsonb;
  v_insert_cols text;
  v_insert_expr text;
  v_item_fk text;
  v_item_fk_count integer := 0;
  v_actor_role text;
  v_field text;
  v_source_columns text[];
  v_parent_columns text[];
  v_source_fk boolean;
  v_target_fk boolean;
  v_target_type_oid oid;
  v_target_relation regclass;
begin
  if p_source_type is null or p_target_type is null
     or p_source_type not in ('LOADING','UNLOADING','BACKLOAD','OFFLOAD')
     or p_target_type not in ('LOADING','UNLOADING','BACKLOAD','OFFLOAD') then
    raise exception using errcode='22023', message='Source and target types must be LOADING, UNLOADING, BACKLOAD, or OFFLOAD.';
  end if;
  if p_source_type = p_target_type then
    raise exception using errcode='22023', message='Source and target event types must differ.';
  end if;
  if p_source_id is null or p_actor_profile_id is null then
    raise exception using errcode='42501', message='An authenticated ADMIN or STAFF actor and source report are required.';
  end if;
  if p_target_fields is null or jsonb_typeof(p_target_fields) <> 'object' then
    raise exception using errcode='22023', message='target_fields must be a JSON object.';
  end if;

  select upper(role::text) into v_actor_role
  from public.profiles where id=p_actor_profile_id;
  if coalesce(v_actor_role,'') not in ('ADMIN','STAFF') then
    raise exception using errcode='42501', message='Only an ADMIN or STAFF actor may convert operational reports.';
  end if;

  v_source_table := case p_source_type when 'LOADING' then 'loading_reports' when 'UNLOADING' then 'unloading_reports' when 'BACKLOAD' then 'backloads' else 'offloads' end;
  v_target_table := case p_target_type when 'LOADING' then 'loading_reports' when 'UNLOADING' then 'unloading_reports' when 'BACKLOAD' then 'backloads' else 'offloads' end;
  v_source_receipt_col := case p_source_type when 'LOADING' then 'loading_report_id' when 'UNLOADING' then 'unloading_report_id' when 'BACKLOAD' then 'backload_id' else 'offload_id' end;
  v_target_receipt_col := case p_target_type when 'LOADING' then 'loading_report_id' when 'UNLOADING' then 'unloading_report_id' when 'BACKLOAD' then 'backload_id' else 'offload_id' end;
  v_target_relation := to_regclass(format('public.%I',v_target_table));
  if to_regclass(format('public.%I',v_source_table)) is null or v_target_relation is null
     or to_regclass('public.report_receipts') is null
     or to_regclass('public.operations_report_conversions') is null then
    raise exception using errcode='55000', message='A required report, receipt, or conversion-history table is missing; conversion is disabled.';
  end if;

  -- Lock currently attached receipts in stable order before locking the parent,
  -- matching the checked-in receipt trigger's receipt-row -> parent-row order.
  -- This scan must be NOWAIT: a receipt UPDATE already owns its tuple before
  -- its BEFORE trigger locks the NEW parent. Waiting here could participate in
  -- a cycle if another transaction owns a parent lock and is waiting on receipt
  -- work. Fail as a retryable conflict instead of waiting before we own source.
  begin
    perform r.id from public.report_receipts r
      where to_jsonb(r)->>v_source_receipt_col=p_source_id::text
      order by r.id for update nowait;
  exception when lock_not_available then
    raise exception using errcode='40001',
      message='A receipt is being changed for this report. Retry the conversion.';
  end;

  -- This row lock serializes repeated conversions of one source. The unique
  -- (source_type, source_id) history key is the final duplicate guard.
  execute format('select to_jsonb(t) from public.%I t where id=$1 for update',v_source_table)
    into v_source_row using p_source_id;
  if v_source_row is null then
    raise exception using errcode='P0002', message='Source report was not found.';
  end if;
  v_trip_id := nullif(v_source_row->>'trip_id','')::uuid;
  v_stop_id := nullif(v_source_row->>'trip_stop_id','')::uuid;
  if v_trip_id is null then
    raise exception using errcode='23514', message='Source report has no trip scope; conversion is not allowed.';
  end if;

  -- A receipt write that started after the first pass may hold its receipt row
  -- while waiting for this parent. Never wait for that row while holding the
  -- parent: NOWAIT converts the cycle into a retryable transaction failure.
  -- A new, uncommitted receipt INSERT is invisible here but waits for this
  -- parent; after conversion commits, its receipt guard sees the ledger row
  -- and rejects attachment to the converted source.
  begin
    perform r.id from public.report_receipts r
      where to_jsonb(r)->>v_source_receipt_col=p_source_id::text
      order by r.id for update nowait;
  exception when lock_not_available then
    raise exception using errcode='40001',
      message='A receipt is being changed for this report. Retry the conversion.';
  end;

  -- Read and lock the exact stop named by the source. The full stop image is
  -- retained because Unloading timestamps and remarks live there.
  if v_stop_id is not null then
    select to_jsonb(s) into v_source_stop
    from public.trip_stops s where s.id=v_stop_id and s.trip_id=v_trip_id for share;
    if not found then
      raise exception using errcode='23514', message='Source stop does not belong to the source trip.';
    end if;
  end if;
  if p_source_type='LOADING' and p_target_type='UNLOADING' then
    raise exception using errcode='22023', message='LOADING has no stop association or Unloading timeline to map; this conversion is not supported.';
  end if;
  if p_target_type='UNLOADING' then
    if v_stop_id is null then
      raise exception using errcode='22023', message='Conversion to UNLOADING requires an existing source stop; no stop will be inferred.';
    end if;
    if nullif(v_source_stop->>'arrival_time','') is null
       and nullif(v_source_stop->>'start_unloading_time','') is null
       and nullif(v_source_stop->>'finish_unloading_time','') is null then
      raise exception using errcode='22023', message='The source stop has no saved arrival or unloading timestamp; a meaningful UNLOADING target cannot be created.';
    end if;
  end if;

  -- Validate scope and ID generation assumptions before attempting an insert.
  if not exists (
    select 1 from pg_attribute a where a.attrelid=v_target_relation
      and a.attname='trip_id' and a.atttypid='uuid'::regtype and a.attnotnull
      and a.attnum>0 and not a.attisdropped
  ) then
    raise exception using errcode='55000', message='Target schema must provide a required UUID trip_id column; conversion is disabled.';
  end if;
  if not exists (
    select 1 from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum
    where a.attrelid=v_target_relation and a.attname='id' and a.atttypid='uuid'::regtype
      and (a.attidentity<>'' or a.attgenerated<>'' or d.adbin is not null)
  ) then
    raise exception using errcode='55000', message='Target schema does not generate a UUID id; conversion is disabled.';
  end if;
  if p_target_type='UNLOADING' and not exists (
    select 1 from pg_attribute a where a.attrelid=v_target_relation
      and a.attname='trip_stop_id' and a.atttypid='uuid'::regtype and a.attnotnull
  ) then
    raise exception using errcode='55000', message='Unloading target schema must require UUID trip_stop_id; conversion is disabled.';
  end if;
  if p_target_type in ('BACKLOAD','OFFLOAD') and not exists (
    select 1 from pg_attribute a where a.attrelid=v_target_relation
      and a.attname='trip_stop_id' and a.atttypid='uuid'::regtype and not a.attnotnull
  ) then
    raise exception using errcode='55000', message='Cargo target schema must provide optional UUID trip_stop_id; conversion is disabled.';
  end if;

  -- Discover the source child FK and snapshot complete rows. Backload and
  -- Offload child schemas differ (including Offload item reason), so rows are
  -- deliberately not moved or coerced into the target item table. They remain
  -- attached to the immutable source and are retained in the history snapshot.
  select count(*),min(a.attname) into v_item_fk_count,v_item_fk
  from pg_constraint c
  join pg_class child on child.oid=c.conrelid
  join pg_namespace ns on ns.oid=child.relnamespace
  join pg_attribute a on a.attrelid=child.oid and a.attnum=c.conkey[1]
  where c.contype='f' and ns.nspname='public'
    and child.relname=case p_source_type when 'BACKLOAD' then 'backload_items' when 'OFFLOAD' then 'offload_items' else '' end
    and a.attname=case p_source_type when 'BACKLOAD' then 'backload_id' when 'OFFLOAD' then 'offload_id' else '' end
    and array_length(c.conkey,1)=1 and array_length(c.confkey,1)=1
    and c.confrelid=to_regclass(format('public.%I',v_source_table))
    and c.confkey[1]=(select parent_id.attnum from pg_attribute parent_id
      where parent_id.attrelid=to_regclass(format('public.%I',v_source_table)) and parent_id.attname='id'
        and parent_id.attnum>0 and not parent_id.attisdropped);
  if p_source_type in ('BACKLOAD','OFFLOAD') and v_item_fk_count<>1 then
    raise exception using errcode='55000', message='Could not identify exactly one source cargo item parent relationship; conversion is disabled.';
  end if;
  if v_item_fk is not null then
    execute format('select coalesce(jsonb_agg(to_jsonb(i) order by i.id), ''[]''::jsonb) from public.%I i where i.%I=$1',
      case p_source_type when 'BACKLOAD' then 'backload_items' when 'OFFLOAD' then 'offload_items' else '' end,v_item_fk)
      into v_items using p_source_id;
  elsif p_source_type in ('BACKLOAD','OFFLOAD') then
    raise exception using errcode='55000', message='Could not verify the cargo child relationship; conversion is disabled.';
  end if;
  -- Snapshot locked receipts including every metadata column before transfer.
  select coalesce(jsonb_agg(to_jsonb(r) order by r.id),'[]'::jsonb) into v_receipts
  from public.report_receipts r where to_jsonb(r)->>v_source_receipt_col=p_source_id::text;
  if exists (
    select 1 from public.report_receipts r
    where to_jsonb(r)->>v_source_receipt_col=p_source_id::text
      and num_nonnulls(r.loading_report_id,r.unloading_report_id,r.backload_id,r.offload_id)<>1
  ) then
    raise exception using errcode='23514', message='A source receipt does not have exactly one parent; conversion was rejected.';
  end if;
  if exists (
    select 1 from jsonb_array_elements(v_receipts) receipt
    where receipt->>'trip_id' is distinct from v_trip_id::text
       or (p_target_type='UNLOADING' and receipt->>'trip_stop_id' is distinct from v_stop_id::text)
  ) then
    raise exception using errcode='23514', message='Receipt trip/stop scope cannot be preserved for this target; conversion was rejected.';
  end if;

  -- Check exact receipt FK column correspondence (not merely that a column
  -- happens to participate in some FK to the target table).
  v_source_columns := case p_source_type
    when 'UNLOADING' then array['unloading_report_id','trip_stop_id','trip_id']
    when 'LOADING' then array['loading_report_id','trip_id']
    when 'BACKLOAD' then array['backload_id','trip_id']
    else array['offload_id','trip_id'] end;
  v_parent_columns := case p_source_type when 'UNLOADING' then array['id','trip_stop_id','trip_id'] else array['id','trip_id'] end;
  select exists (
    select 1 from pg_constraint c where c.contype='f' and c.conrelid='public.report_receipts'::regclass
      and c.confrelid=to_regclass(format('public.%I',v_source_table))
      and (select array_agg(a.attname::text order by k.ordinality) from unnest(c.conkey) with ordinality k(attnum,ordinality)
        join pg_attribute a on a.attrelid=c.conrelid and a.attnum=k.attnum)=v_source_columns
      and (select array_agg(a.attname::text order by k.ordinality) from unnest(c.confkey) with ordinality k(attnum,ordinality)
        join pg_attribute a on a.attrelid=c.confrelid and a.attnum=k.attnum)=v_parent_columns
  ) into v_source_fk;
  v_source_columns := case p_target_type
    when 'UNLOADING' then array['unloading_report_id','trip_stop_id','trip_id']
    when 'LOADING' then array['loading_report_id','trip_id']
    when 'BACKLOAD' then array['backload_id','trip_id']
    else array['offload_id','trip_id'] end;
  v_parent_columns := case p_target_type when 'UNLOADING' then array['id','trip_stop_id','trip_id'] else array['id','trip_id'] end;
  select exists (
    select 1 from pg_constraint c where c.contype='f' and c.conrelid='public.report_receipts'::regclass
      and c.confrelid=to_regclass(format('public.%I',v_target_table))
      and (select array_agg(a.attname::text order by k.ordinality) from unnest(c.conkey) with ordinality k(attnum,ordinality)
        join pg_attribute a on a.attrelid=c.conrelid and a.attnum=k.attnum)=v_source_columns
      and (select array_agg(a.attname::text order by k.ordinality) from unnest(c.confkey) with ordinality k(attnum,ordinality)
        join pg_attribute a on a.attrelid=c.confrelid and a.attnum=k.attnum)=v_parent_columns
  ) into v_target_fk;
  if not coalesce(v_source_fk,false) or not coalesce(v_target_fk,false) then
    raise exception using errcode='55000', message='The exact source or target receipt scope foreign key is missing; conversion is disabled.';
  end if;
  if not exists (select 1 from pg_attribute a where a.attrelid='public.report_receipts'::regclass and a.attname=v_source_receipt_col and a.atttypid='uuid'::regtype)
     or not exists (select 1 from pg_attribute a where a.attrelid='public.report_receipts'::regclass and a.attname=v_target_receipt_col and a.atttypid='uuid'::regtype) then
    raise exception using errcode='55000', message='Receipt parent columns are missing or are not UUIDs; conversion is disabled.';
  end if;

  -- Build an explicit target mapping. Only source trip/stop scope is carried;
  -- event-specific fields are re-entered for the target and old values remain
  -- in source_snapshot. Target type dictates the permitted input fields.
  v_target_row := jsonb_build_object('trip_id',v_trip_id);
  if p_target_type='UNLOADING' or (p_target_type in ('BACKLOAD','OFFLOAD') and v_stop_id is not null) then
    v_target_row := v_target_row || jsonb_build_object('trip_stop_id',v_stop_id);
  end if;
  if p_target_type='LOADING' then
    if exists (select 1 from jsonb_object_keys(p_target_fields) f(key) where key not in ('warehouse_arrival_at','loading_start_at','loading_finished_at')) then
      raise exception using errcode='22023', message='Only Loading timestamp fields may be supplied for a LOADING target.';
    end if;
    if not (p_target_fields ?| array['warehouse_arrival_at','loading_start_at','loading_finished_at'])
       or not exists (select 1 from jsonb_each(p_target_fields) f where f.key in ('warehouse_arrival_at','loading_start_at','loading_finished_at') and jsonb_typeof(f.value)='string' and nullif(btrim(f.value #>> '{}'),'') is not null) then
      raise exception using errcode='22023', message='Supply at least one nonempty target Loading timestamp; source timestamps are not reinterpreted.';
    end if;
    foreach v_field in array array['warehouse_arrival_at','loading_start_at','loading_finished_at'] loop
      if p_target_fields ? v_field then
        select a.atttypid into v_target_type_oid from pg_attribute a where a.attrelid=v_target_relation and a.attname=v_field and a.attnum>0 and not a.attisdropped;
        if v_target_type_oid is distinct from 'timestamp with time zone'::regtype then
          raise exception using errcode='55000', message=format('LOADING target field %s is missing or is not timestamptz; conversion is disabled.',v_field);
        end if;
      end if;
    end loop;
    v_target_row := v_target_row || p_target_fields;
  elsif p_target_type in ('BACKLOAD','OFFLOAD') then
    if exists (select 1 from jsonb_object_keys(p_target_fields) f(key) where key not in ('reason','number_of_boxes','comments')) then
      raise exception using errcode='22023', message='Only reason, number_of_boxes, and comments may be supplied for a cargo target.';
    end if;
    if jsonb_typeof(p_target_fields->'reason') is distinct from 'string' or nullif(btrim(p_target_fields->>'reason'),'') is null then
      raise exception using errcode='22023', message='Supply a new nonempty reason for the target cargo report; source reason semantics are not assumed equivalent.';
    end if;
    if p_target_fields ? 'number_of_boxes' and p_target_fields->'number_of_boxes' <> 'null'::jsonb then
      if jsonb_typeof(p_target_fields->'number_of_boxes') <> 'number'
         or (p_target_fields->>'number_of_boxes')::numeric < 0
         or (p_target_fields->>'number_of_boxes')::numeric <> trunc((p_target_fields->>'number_of_boxes')::numeric) then
        raise exception using errcode='22023', message='number_of_boxes must be a non-negative whole number or null.';
      end if;
    end if;
    foreach v_field in array array['reason','number_of_boxes','comments'] loop
      if p_target_fields ? v_field then
        select a.atttypid into v_target_type_oid from pg_attribute a where a.attrelid=v_target_relation and a.attname=v_field and a.attnum>0 and not a.attisdropped;
        if v_target_type_oid is null then
          raise exception using errcode='55000', message=format('Cargo target field %s is missing; conversion is disabled.',v_field);
        end if;
        if v_field in ('reason','comments') and (select t.typcategory from pg_type t where t.oid=v_target_type_oid) <> 'S' then
          raise exception using errcode='55000', message=format('Cargo target field %s is not a string column; conversion is disabled.',v_field);
        end if;
        if v_field='number_of_boxes' and v_target_type_oid not in ('smallint'::regtype,'integer'::regtype,'bigint'::regtype,'numeric'::regtype) then
          raise exception using errcode='55000', message='Cargo target number_of_boxes is not a numeric column; conversion is disabled.';
        end if;
      end if;
    end loop;
    v_target_row := v_target_row || p_target_fields;
  elsif p_target_type='UNLOADING' and p_target_fields <> '{}'::jsonb then
    raise exception using errcode='22023', message='UNLOADING timestamps and remarks belong to the existing trip_stops row and cannot be overridden during conversion.';
  end if;

  -- Validate fields, defaults, and every required target column before insert.
  if exists (
    select 1 from jsonb_object_keys(v_target_row) f(key)
    where not exists (select 1 from pg_attribute a where a.attrelid=v_target_relation and a.attname=f.key and a.attnum>0 and not a.attisdropped)
  ) then
    raise exception using errcode='55000', message='A mapped target field is absent from the target report schema; conversion is disabled.';
  end if;
  if exists (
    select 1 from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum
    where a.attrelid=v_target_relation and a.attnum>0 and not a.attisdropped and a.attnotnull
      and d.adbin is null and a.attidentity='' and a.attgenerated=''
      and (not (v_target_row ? a.attname) or v_target_row->a.attname='null'::jsonb)
  ) then
    raise exception using errcode='22023', message='A required target field has no supplied nonnull value or database default; conversion is disabled.';
  end if;

  -- Loading and Unloading uniqueness is an invariant. Verify its exact
  -- one-column index before relying on it; concurrent calls are finally
  -- arbitrated by that unique index. Cargo scope has no assumed uniqueness;
  -- any actual target constraint is enforced by INSERT below.
  if p_target_type='LOADING' then
    if not exists (select 1 from pg_index i join pg_attribute a on a.attrelid=i.indrelid and a.attname='trip_id'
      where i.indrelid=v_target_relation and i.indisunique and i.indpred is null and i.indnkeyatts=1 and i.indkey[0]=a.attnum) then
      raise exception using errcode='55000', message='Schema is missing the required unique Loading-per-trip constraint; conversion is disabled.';
    end if;
    if exists (select 1 from public.loading_reports where trip_id=v_trip_id) then
      raise exception using errcode='23505', message='A LOADING report already exists for this trip.';
    end if;
  elsif p_target_type='UNLOADING' then
    if not exists (select 1 from pg_index i join pg_attribute a on a.attrelid=i.indrelid and a.attname='trip_stop_id'
      where i.indrelid=v_target_relation and i.indisunique and i.indpred is null and i.indnkeyatts=1 and i.indkey[0]=a.attnum) then
      raise exception using errcode='55000', message='Schema is missing the required unique Unloading-per-stop constraint; conversion is disabled.';
    end if;
    if exists (select 1 from public.unloading_reports where trip_stop_id=v_stop_id) then
      raise exception using errcode='23505', message='An UNLOADING report already exists for this stop.';
    end if;
  end if;

  select string_agg(format('%I',a.attname),',' order by a.attnum),
         string_agg(format('(jsonb_populate_record(null::public.%I,$1)).%I',v_target_table,a.attname),',' order by a.attnum)
    into v_insert_cols,v_insert_expr
  from pg_attribute a where a.attrelid=v_target_relation and a.attnum>0 and not a.attisdropped
    and v_target_row ? a.attname;
  if v_insert_cols is null then
    raise exception using errcode='55000', message='Target report schema has no insertable mapped fields.';
  end if;
  execute format('insert into public.%I (%s) select %s returning id',v_target_table,v_insert_cols,v_insert_expr)
    into v_target_id using v_target_row;
  if v_target_id is null then
    raise exception using errcode='55000', message='Target report did not receive a generated UUID; conversion was rolled back.';
  end if;

  v_snapshot := jsonb_build_object(
    'parent',v_source_row,
    'stop',v_source_stop,
    'receipts',v_receipts,
    'mapping_policy','Only trip/stop scope is copied automatically. Target event-specific data is explicitly supplied or reused from the existing Unloading stop timeline. Unmatched source values remain in this snapshot.'
  );

  -- Reparent only the receipt FK. The receipt guard and existing scope/FK
  -- triggers run normally. Receipt IDs and all metadata remain untouched.
  execute format('update public.report_receipts set %I=$1, %I=null where %I=$2',
    v_target_receipt_col,v_source_receipt_col,v_source_receipt_col)
    using v_target_id,p_source_id;

  insert into public.operations_report_conversions
    (source_type,source_id,target_type,target_id,trip_id,trip_stop_id,actor_profile_id,source_snapshot,source_items_snapshot)
  values (p_source_type,p_source_id,p_target_type,v_target_id,v_trip_id,
    nullif(v_source_row->>'trip_stop_id','')::uuid,p_actor_profile_id,v_snapshot,v_items);

  return jsonb_build_object('source_type',p_source_type,'source_id',p_source_id,
    'target_type',p_target_type,'target_id',v_target_id,'trip_id',v_trip_id,
    'trip_stop_id',nullif(v_source_row->>'trip_stop_id',''));
end;
$function$
CREATE OR REPLACE FUNCTION public.guard_converted_operations_report_source_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if exists (select 1 from public.operations_report_conversions c where c.source_type=TG_ARGV[0] and c.source_id=OLD.id) then
    raise exception using errcode='55000', message='Converted source report is immutable.';
  end if;
  if TG_OP='DELETE' then return OLD; end if;
  return NEW;
end;
$function$
CREATE OR REPLACE FUNCTION public.planned_route_write_v1(p_actor uuid, p_assignment uuid, p_action text, p_token uuid, p_context text, p_fingerprint text, p_expected bigint DEFAULT 0, p_geometry jsonb DEFAULT NULL::jsonb, p_distance double precision DEFAULT NULL::double precision, p_duration double precision DEFAULT NULL::double precision, p_error text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE ctx jsonb; r public.trip_route_cache%ROWTYPE; used integer; minute_start timestamptz:=date_trunc('minute',clock_timestamp()); point jsonb;
BEGIN
 IF NOT EXISTS(SELECT FROM public.profiles WHERE id=p_actor AND role IN('ADMIN','STAFF') FOR SHARE) THEN
  RAISE EXCEPTION 'Management routing access required.' USING ERRCODE='42501'; END IF;
 IF p_action NOT IN('CLAIM','FINISH','FAIL') OR p_token IS NULL THEN
  RAISE EXCEPTION 'Invalid planned routing action.' USING ERRCODE='22023'; END IF;
 ctx:=public.planned_route_context_v1(p_assignment,true);
 IF p_action IN('CLAIM','FINISH') THEN
  IF ctx IS NULL OR NOT coalesce((ctx->>'active')::boolean,false) OR ctx->>'context_token' IS DISTINCT FROM p_context
   OR p_fingerprint IS NULL OR p_fingerprint !~ '^[a-f0-9]{64}$' THEN RETURN false; END IF;
  IF jsonb_array_length(ctx->'destinations') NOT BETWEEN 1 AND 24 THEN
   RAISE EXCEPTION 'Planned route requires 1 to 24 delivery stops; none may be omitted.' USING ERRCODE='22023'; END IF;
  FOR point IN SELECT ctx->'origin' UNION ALL SELECT value FROM jsonb_array_elements(ctx->'destinations') LOOP
   IF jsonb_typeof(point->'latitude') IS DISTINCT FROM 'number' OR jsonb_typeof(point->'longitude') IS DISTINCT FROM 'number'
    OR NOT((point->>'latitude')::numeric BETWEEN -90 AND 90 AND (point->>'longitude')::numeric BETWEEN -180 AND 180) THEN
    RAISE EXCEPTION 'Warehouse or delivery-stop coordinates missing or invalid.' USING ERRCODE='22023'; END IF;
  END LOOP;
 END IF;
 IF p_action='CLAIM' THEN
  -- Same advisory lock and SAME counters as existing remaining-route RPC: combined
  -- company-wide budget is 30 requests/minute, not 30 per route variant/replica.
  PERFORM pg_advisory_xact_lock(771004219);
  SELECT coalesce(sum(window_requests),0) INTO used FROM public.trip_route_cache WHERE request_window=minute_start;
  IF used>=30 THEN RETURN false; END IF;
  SELECT * INTO r FROM public.trip_route_cache WHERE assignment_id=p_assignment FOR UPDATE;
  IF FOUND AND (r.planned_revision<>p_expected OR r.planned_lease_expires_at>clock_timestamp() OR r.planned_retry_after>clock_timestamp()) THEN RETURN false; END IF;
  IF NOT FOUND AND p_expected<>0 THEN RETURN false; END IF;
  -- Zero sentinel is used ONLY for a new remaining-cache placeholder; remaining
  -- route_geometry stays NULL. Its original revision/lease/fingerprint are never
  -- updated by a planned refresh of an existing row.
  INSERT INTO public.trip_route_cache(assignment_id,destination_fingerprint,planned_lease_token,planned_lease_expires_at,planned_revision,directions_requests,request_window,window_requests)
   VALUES(p_assignment,repeat('0',64),p_token,clock_timestamp()+interval '1 minute',1,1,minute_start,1)
  ON CONFLICT(assignment_id) DO UPDATE SET planned_lease_token=p_token,planned_lease_expires_at=clock_timestamp()+interval '1 minute',
   planned_revision=public.trip_route_cache.planned_revision+1,directions_requests=public.trip_route_cache.directions_requests+1,
   request_window=minute_start,window_requests=CASE WHEN public.trip_route_cache.request_window=minute_start THEN public.trip_route_cache.window_requests+1 ELSE 1 END;
  RETURN true;
 END IF;
 SELECT * INTO r FROM public.trip_route_cache WHERE assignment_id=p_assignment FOR UPDATE;
 IF NOT FOUND OR r.planned_lease_token IS DISTINCT FROM p_token THEN RETURN false; END IF;
 IF p_action='FAIL' THEN
  UPDATE public.trip_route_cache SET planned_lease_token=NULL,planned_lease_expires_at=NULL,
   planned_retry_after=clock_timestamp()+CASE WHEN p_error='ROUTE_RATE_LIMITED' THEN interval '5 minutes' ELSE interval '1 minute' END,
   planned_error=left(coalesce(p_error,'ROUTE_UNAVAILABLE'),100),planned_revision=planned_revision+1 WHERE assignment_id=p_assignment;
  RETURN true;
 END IF;
 IF r.planned_lease_expires_at IS NULL OR r.planned_lease_expires_at<clock_timestamp() THEN RETURN false; END IF;
 IF p_geometry IS NULL OR p_geometry->>'type' IS DISTINCT FROM 'LineString' OR jsonb_typeof(p_geometry->'coordinates') IS DISTINCT FROM 'array'
  OR jsonb_array_length(p_geometry->'coordinates') NOT BETWEEN 2 AND 20000 OR octet_length(p_geometry::text)>1048576
  OR p_distance IS NULL OR p_duration IS NULL OR NOT(p_distance BETWEEN 0 AND 1000000000 AND p_duration BETWEEN 0 AND 1000000000) THEN
  RAISE EXCEPTION 'Invalid planned road route.' USING ERRCODE='22023'; END IF;
 FOR point IN SELECT value FROM jsonb_array_elements(p_geometry->'coordinates') LOOP
  IF jsonb_typeof(point) IS DISTINCT FROM 'array' OR jsonb_array_length(point)<>2
   OR jsonb_typeof(point->0) IS DISTINCT FROM 'number' OR jsonb_typeof(point->1) IS DISTINCT FROM 'number'
   OR NOT((point->>0)::numeric BETWEEN -180 AND 180 AND (point->>1)::numeric BETWEEN -90 AND 90) THEN
   RAISE EXCEPTION 'Invalid planned route coordinate order or bounds.' USING ERRCODE='22023'; END IF;
 END LOOP;
 UPDATE public.trip_route_cache SET planned_fingerprint=p_fingerprint,planned_geometry=p_geometry,
  planned_distance_meters=p_distance,planned_duration_seconds=p_duration,planned_calculated_at=clock_timestamp(),planned_expires_at=clock_timestamp()+interval '1 hour',
  planned_lease_token=NULL,planned_lease_expires_at=NULL,planned_retry_after=NULL,planned_error=NULL,planned_revision=planned_revision+1
 WHERE assignment_id=p_assignment;
 RETURN true;
END $function$
CREATE OR REPLACE FUNCTION public.guard_converted_report_receipt_parent_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_old_parent_id uuid;
  v_old_parent_type text;
  v_parent_id uuid;
  v_parent_type text;
  v_parent_table text;
  v_locked_id uuid;
begin
  if TG_OP='UPDATE' then
    if num_nonnulls(OLD.loading_report_id,OLD.unloading_report_id,OLD.backload_id,OLD.offload_id)<>1 then
      raise exception using errcode='23514', message='An existing report receipt must reference exactly one report parent.';
    end if;
    if OLD.loading_report_id is not null then v_old_parent_id:=OLD.loading_report_id; v_old_parent_type:='LOADING';
    elsif OLD.unloading_report_id is not null then v_old_parent_id:=OLD.unloading_report_id; v_old_parent_type:='UNLOADING';
    elsif OLD.backload_id is not null then v_old_parent_id:=OLD.backload_id; v_old_parent_type:='BACKLOAD';
    else v_old_parent_id:=OLD.offload_id; v_old_parent_type:='OFFLOAD'; end if;
    -- During the conversion RPC this is checked before the ledger row is
    -- inserted, so its atomic source -> target receipt handoff is allowed.
    -- Later attempts to detach a receipt from a converted source are rejected.
    if exists (select 1 from public.operations_report_conversions c
      where c.source_type=v_old_parent_type and c.source_id=v_old_parent_id) then
      raise exception using errcode='55000', message='A receipt cannot be detached from a converted source report.';
    end if;
  end if;
  if num_nonnulls(NEW.loading_report_id,NEW.unloading_report_id,NEW.backload_id,NEW.offload_id)<>1 then
    raise exception using errcode='23514', message='A report receipt must reference exactly one report parent.';
  end if;
  if NEW.loading_report_id is not null then v_parent_id:=NEW.loading_report_id; v_parent_type:='LOADING'; v_parent_table:='loading_reports';
  elsif NEW.unloading_report_id is not null then v_parent_id:=NEW.unloading_report_id; v_parent_type:='UNLOADING'; v_parent_table:='unloading_reports';
  elsif NEW.backload_id is not null then v_parent_id:=NEW.backload_id; v_parent_type:='BACKLOAD'; v_parent_table:='backloads';
  else v_parent_id:=NEW.offload_id; v_parent_type:='OFFLOAD'; v_parent_table:='offloads'; end if;
  execute format('select id from public.%I where id=$1 for update',v_parent_table) into v_locked_id using v_parent_id;
  if v_locked_id is null then
    raise exception using errcode='23503', message='Receipt report parent does not exist.';
  end if;
  if exists (select 1 from public.operations_report_conversions c where c.source_type=v_parent_type and c.source_id=v_parent_id) then
    raise exception using errcode='55000', message='A converted source report cannot receive or retain new receipts.';
  end if;
  return NEW;
end;
$function$
CREATE OR REPLACE FUNCTION public.guard_converted_operations_report_item_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_parent_column text := TG_ARGV[0];
  v_parent_type text := TG_ARGV[1];
  v_parent_table text := case TG_ARGV[1] when 'BACKLOAD' then 'backloads' else 'offloads' end;
  v_parent_ids uuid[];
  v_id uuid;
  v_locked_id uuid;
begin
  if TG_OP='INSERT' then v_parent_ids:=array[nullif(to_jsonb(NEW)->>v_parent_column,'')::uuid];
  elsif TG_OP='DELETE' then v_parent_ids:=array[nullif(to_jsonb(OLD)->>v_parent_column,'')::uuid];
  else v_parent_ids:=array[nullif(to_jsonb(OLD)->>v_parent_column,'')::uuid,nullif(to_jsonb(NEW)->>v_parent_column,'')::uuid]; end if;
  for v_id in select distinct parents.parent_id from unnest(v_parent_ids) as parents(parent_id)
    where parents.parent_id is not null order by parents.parent_id loop
    execute format('select id from public.%I where id=$1 for update',v_parent_table) into v_locked_id using v_id;
    if exists (select 1 from public.operations_report_conversions c where c.source_type=v_parent_type and c.source_id=v_id) then
      raise exception using errcode='55000', message='Items belonging to a converted source report are immutable.';
    end if;
  end loop;
  if TG_OP='DELETE' then return OLD; end if;
  return NEW;
end;
$function$
CREATE OR REPLACE FUNCTION public.guard_converted_unloading_stop_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_converted boolean;
  v_column text;
  v_protected text[] := array['id','trip_id','stop_sequence','store_id','customer_id','delivery_status','arrival_time','start_unloading_time','finish_unloading_time','departure_time','remarks'];
begin
  select exists (
    select 1 from public.unloading_reports ur
    join public.operations_report_conversions c on c.source_type='UNLOADING' and c.source_id=ur.id
    where ur.trip_stop_id=OLD.id
  ) into v_converted;
  if not v_converted then
    if TG_OP='DELETE' then return OLD; end if;
    return NEW;
  end if;
  if TG_OP='DELETE' then
    raise exception using errcode='55000', message='Stop identity or timeline belongs to a converted Unloading source.';
  end if;
  foreach v_column in array v_protected loop
    if to_jsonb(NEW)->v_column is distinct from to_jsonb(OLD)->v_column then
      raise exception using errcode='55000', message=format('Stop field %s belongs to a converted Unloading source and is immutable.',v_column);
    end if;
  end loop;
  return NEW;
end;
$function$
CREATE OR REPLACE FUNCTION public.bump_transaction_dr_version()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  NEW.dr_version := OLD.dr_version + 1;
  RETURN NEW;
END;
$function$
CREATE OR REPLACE FUNCTION public.create_offload_with_item_v1(p_report jsonb, p_item jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE saved public.offloads; stop_record public.trip_stops; trip_record public.trips;
BEGIN
  SELECT * INTO trip_record FROM public.trips WHERE id=(p_report->>'trip_id')::uuid FOR SHARE;
  IF NOT FOUND OR trip_record.archived_at IS NOT NULL THEN RAISE EXCEPTION 'Trip is unavailable or archived'; END IF;
  IF p_report->>'trip_stop_id' IS NOT NULL THEN
    SELECT * INTO stop_record FROM public.trip_stops WHERE id=(p_report->>'trip_stop_id')::uuid AND trip_id=trip_record.id FOR SHARE;
    IF NOT FOUND OR stop_record.archived_at IS NOT NULL THEN RAISE EXCEPTION 'Transaction is unavailable or archived'; END IF;
  END IF;
  INSERT INTO public.offloads(trip_id,trip_stop_id,reason,number_of_boxes,comments,created_by,submitted_by,submitted_at,reported_at,reported_by,report_date)
  VALUES(trip_record.id,(p_report->>'trip_stop_id')::uuid,p_report->>'reason',(p_report->>'number_of_boxes')::numeric,p_report->>'comments',
    (p_report->>'created_by')::uuid,(p_report->>'submitted_by')::uuid,(p_report->>'submitted_at')::timestamptz,
    (p_report->>'reported_at')::timestamptz,(p_report->>'reported_by')::uuid,((p_report->>'reported_at')::timestamptz AT TIME ZONE 'Asia/Manila')::date)
  RETURNING * INTO saved;
  IF p_item->>'quantity' IS NOT NULL OR p_item->>'total_cbm' IS NOT NULL THEN
    IF (p_item->>'quantity')::numeric < 0 OR (p_item->>'total_cbm')::numeric < 0
       OR COALESCE(p_item->>'quantity','') IN ('NaN','Infinity','-Infinity') OR COALESCE(p_item->>'total_cbm','') IN ('NaN','Infinity','-Infinity')
    THEN RAISE EXCEPTION 'Offload values must be finite and non-negative'; END IF;
    INSERT INTO public.offload_items(offload_id,trip_line_item_id,quantity,total_cbm)
    VALUES(saved.id,NULL,(p_item->>'quantity')::numeric,(p_item->>'total_cbm')::numeric);
  END IF;
  RETURN to_jsonb(saved);
END;
$function$
CREATE OR REPLACE FUNCTION public.delete_offload_with_cleanup_v1(p_offload_id uuid, p_actor_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_report public.offloads%ROWTYPE;
  v_job public.offload_deletion_jobs%ROWTYPE;
  v_receipts jsonb;
  v_items jsonb;
  v_paths text[];
  v_prefix text;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id=p_actor_id AND role IN ('ADMIN','STAFF')) THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='Only ADMIN or STAFF may delete Offload reports.';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('offload_delete:'||p_offload_id::text,0));
  SELECT * INTO v_job FROM public.offload_deletion_jobs WHERE offload_id=p_offload_id;
  IF FOUND THEN RETURN to_jsonb(v_job); END IF;
  SELECT * INTO v_report FROM public.offloads WHERE id=p_offload_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002', MESSAGE='Offload report not found.'; END IF;
  IF EXISTS (SELECT 1 FROM public.operations_report_conversions WHERE
    (source_type='OFFLOAD' AND source_id=p_offload_id) OR (target_type='OFFLOAD' AND target_id=p_offload_id)) THEN
    RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='This report is protected by conversion history.';
  END IF;
  -- Parent lock matches receipt/conversion writers. New receipt writes cannot
  -- attach after the deletion; failed uploads retain existing compensation.
  PERFORM id FROM public.report_receipts WHERE offload_id=p_offload_id FOR UPDATE;
  SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY id),'[]'::jsonb), coalesce(array_agg(storage_path ORDER BY id),'{}'::text[])
    INTO v_receipts,v_paths FROM public.report_receipts r WHERE offload_id=p_offload_id;
  v_prefix := 'operations/'||v_report.trip_id::text||'/offload/'||p_offload_id::text||'/';
  IF EXISTS (SELECT 1 FROM unnest(v_paths) p WHERE
      p IS NULL OR left(p,length(v_prefix))<>v_prefix OR substring(p from length(v_prefix)+1) !~ '^[a-f0-9-]{36}\.(jpg|jpeg|png|webp)$') THEN
    RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='Receipt storage ownership requires review; nothing was deleted.';
  END IF;
  IF EXISTS (SELECT 1 FROM public.documents d CROSS JOIN unnest(v_paths) p WHERE position(p in coalesce(d.file_path,''))>0) THEN
    RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='A receipt is referenced by a retained document; nothing was deleted.';
  END IF;
  PERFORM id FROM public.offload_items WHERE offload_id=p_offload_id FOR UPDATE;
  SELECT coalesce(jsonb_agg(to_jsonb(i) ORDER BY id),'[]'::jsonb) INTO v_items FROM public.offload_items i WHERE offload_id=p_offload_id;
  INSERT INTO public.offload_deletion_jobs(offload_id,trip_id,trip_stop_id,requested_by,state,storage_paths,snapshot,completed_at)
    VALUES(p_offload_id,v_report.trip_id,v_report.trip_stop_id,p_actor_id,
      CASE WHEN cardinality(v_paths)=0 THEN 'COMPLETE' ELSE 'PENDING_STORAGE' END,v_paths,
      jsonb_build_object('actor_profile_id',p_actor_id,'report',to_jsonb(v_report),'items',v_items,'receipts',v_receipts),
      CASE WHEN cardinality(v_paths)=0 THEN now() ELSE NULL END) RETURNING * INTO v_job;
  DELETE FROM public.report_receipts WHERE offload_id=p_offload_id;
  DELETE FROM public.offloads WHERE id=p_offload_id;
  -- Existing FK cascades delete only this Offload's item rows. No trip, stop,
  -- assignment, document, conversion record or other report is selected.
  RETURN to_jsonb(v_job);
END;
$function$
CREATE OR REPLACE FUNCTION public.delete_transaction_with_cleanup_v1(p_trip_id uuid, p_stop_id uuid, p_actor_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_job public.transaction_deletion_jobs%ROWTYPE;
  v_trip jsonb; v_stop jsonb; v_last boolean; v_invalid boolean; v_table text;
  v_rows jsonb; v_snapshot jsonb := '{}'; v_objects jsonb := '[]';
  v_offloads uuid[]; v_backloads uuid[]; v_unloading uuid[]; v_loading uuid[];
  v_flex_ids uuid[];
  v_receipt record; v_image record; v_type text; v_id uuid; v_prefix text;
BEGIN
  IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=p_actor_id AND role IN ('ADMIN','STAFF')) THEN
    RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Only ADMIN or STAFF may delete transactions.';
  END IF;
  -- A short, bounded lock serializes ownership checks with report/item/flex
  -- writers (some logical flex references have no FK). No partial DB deletion.
  PERFORM set_config('lock_timeout','3s',true);
  LOCK TABLE public.trips,public.trip_stops,public.trip_line_items,
    public.trip_truck_assignments,public.trip_events,public.store_calls,
    public.documents,public.incidents,public.demurrages,public.billings,
    public.payables,public.receivables,public.pod_records,public.pod_drive_files,
    public.trip_images,public.offloads,public.offload_items,public.backloads,
    public.backload_items,public.loading_reports,public.unloading_reports,
    public.report_receipts,public.operations_report_conversions,
    public.flex_rows,public.flex_cells,public.driver_trip_updates IN SHARE ROW EXCLUSIVE MODE;
  SELECT * INTO v_job FROM public.transaction_deletion_jobs WHERE transaction_id=coalesce(p_stop_id,p_trip_id);
  IF FOUND THEN
    IF v_job.trip_id<>p_trip_id OR v_job.trip_stop_id IS DISTINCT FROM p_stop_id THEN
      RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='Deletion identity does not match the original transaction.';
    END IF;
    RETURN to_jsonb(v_job);
  END IF;
  SELECT to_jsonb(t) INTO v_trip FROM public.trips t WHERE id=p_trip_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='Trip not found.'; END IF;
  IF p_stop_id IS NOT NULL THEN
    SELECT to_jsonb(s) INTO v_stop FROM public.trip_stops s WHERE id=p_stop_id AND trip_id=p_trip_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='Transaction does not belong to this trip.'; END IF;
  ELSIF EXISTS(SELECT 1 FROM public.trip_stops WHERE trip_id=p_trip_id) THEN
    RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='Select the exact delivery transaction; this trip has stops.';
  END IF;
  v_last := NOT EXISTS(SELECT 1 FROM public.trip_stops WHERE trip_id=p_trip_id AND id IS DISTINCT FROM p_stop_id);
  -- Trip-level legacy updates have no stop identity. Only resolve them when
  -- the parent itself is being removed, under the same transaction and locks.
  IF v_last AND EXISTS(SELECT FROM public.inspect_legacy_pod_ownership_v1(ARRAY[p_trip_id]) WHERE status='BLOCKED') THEN
    RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='Legacy POD ownership/retention is unresolved; inspect the attachment review. Nothing was deleted.';
  END IF;
  IF EXISTS(SELECT FROM public.report_receipts WHERE trip_id=p_trip_id AND (v_last OR trip_stop_id=p_stop_id) AND upload_status='PENDING') THEN
    RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='An image upload is incomplete; nothing was deleted.';
  END IF;
  IF NOT v_last AND EXISTS(SELECT FROM public.trip_images i JOIN public.driver_trip_updates d ON d.pod_image_path=i.storage_path WHERE i.trip_stop_id=p_stop_id AND d.trip_id=p_trip_id) THEN
   RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='This stop has retained driver POD history; use the reviewed whole-trip workflow or retain the stop.';
  END IF;
  IF v_last AND EXISTS(SELECT FROM storage.objects o CROSS JOIN unnest(ARRAY[p_trip_id]) selected_trip
 WHERE ((o.bucket_id='trip-images' AND left(o.name,length('trips/'||selected_trip||'/'))='trips/'||selected_trip||'/' AND NOT EXISTS(SELECT FROM public.trip_images i WHERE i.trip_id=selected_trip AND i.storage_path=o.name))
 OR (o.bucket_id='report-receipts' AND left(o.name,length('operations/'||selected_trip||'/'))='operations/'||selected_trip||'/' AND NOT EXISTS(SELECT FROM public.report_receipts r WHERE r.trip_id=selected_trip AND r.storage_path=o.name)))
 AND NOT EXISTS(SELECT FROM public.transaction_deletion_jobs j CROSS JOIN LATERAL jsonb_array_elements(j.storage_objects) manifest WHERE j.trip_id=selected_trip AND manifest->>'bucket'=o.bucket_id AND manifest->>'path'=o.name AND manifest->>'object_id'=o.id::text AND manifest->>'metadata_fingerprint'=md5(coalesce(o.metadata::text,'')) AND manifest->>'object_version' IS NOT DISTINCT FROM to_jsonb(o)->>'version')) THEN RAISE EXCEPTION 'Unregistered Storage objects require ownership review; nothing was deleted.' USING ERRCODE='55000'; END IF;
  FOREACH v_table IN ARRAY ARRAY['trip_line_items','trip_events','store_calls','documents','incidents','demurrages','pod_records','pod_drive_files','offloads','backloads','unloading_reports','report_receipts'] LOOP
    EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I t WHERE (t.trip_stop_id=$2 AND t.trip_id IS DISTINCT FROM $1) OR (t.trip_id=$1 AND t.trip_stop_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.trip_stops s WHERE s.id=t.trip_stop_id AND s.trip_id=$1)))',v_table) INTO v_invalid USING p_trip_id,p_stop_id;
    IF v_invalid THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='A child record has inconsistent trip/stop ownership; review it before deletion.'; END IF;
  END LOOP;
  IF EXISTS(SELECT 1 FROM public.operations_report_conversions WHERE trip_id=p_trip_id AND (v_last OR trip_stop_id=p_stop_id OR trip_stop_id IS NULL)) THEN
    RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='Conversion history protects this transaction or its shared trip reports.';
  END IF;
  IF EXISTS(SELECT 1 FROM public.billings WHERE trip_id=p_trip_id)
    OR EXISTS(SELECT 1 FROM public.payables WHERE trip_id=p_trip_id)
    OR EXISTS(SELECT 1 FROM public.receivables WHERE trip_id=p_trip_id) THEN
    RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='Trip has billing, payable or receivable records; financial ownership must be reviewed before deletion.';
  END IF;
  IF EXISTS(SELECT 1 FROM public.documents WHERE trip_id=p_trip_id AND (v_last OR trip_stop_id=p_stop_id) AND nullif(btrim(file_path),'') IS NOT NULL)
    OR EXISTS(SELECT 1 FROM public.pod_drive_files WHERE trip_id=p_trip_id AND (v_last OR trip_stop_id=p_stop_id OR pod_record_id IN (SELECT id FROM public.pod_records WHERE trip_id=p_trip_id AND trip_stop_id=p_stop_id))) THEN
    RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='Document or Drive attachments require an ownership/retention review; nothing was deleted.';
  END IF;
  SELECT coalesce(array_agg(id),'{}') INTO v_offloads FROM public.offloads WHERE trip_id=p_trip_id AND (v_last OR trip_stop_id=p_stop_id);
  SELECT coalesce(array_agg(id),'{}') INTO v_backloads FROM public.backloads WHERE trip_id=p_trip_id AND (v_last OR trip_stop_id=p_stop_id);
  SELECT coalesce(array_agg(id),'{}') INTO v_unloading FROM public.unloading_reports WHERE trip_id=p_trip_id AND (v_last OR trip_stop_id=p_stop_id);
  SELECT coalesce(array_agg(id),'{}') INTO v_loading FROM public.loading_reports WHERE trip_id=p_trip_id AND v_last;
  -- A retained report's source items must never be removed by a stop cascade.
  IF EXISTS(SELECT 1 FROM public.offload_items WHERE trip_line_item_id IN (SELECT id FROM public.trip_line_items WHERE trip_id=p_trip_id AND (v_last OR trip_stop_id=p_stop_id)) AND NOT(offload_id=ANY(v_offloads)))
    OR EXISTS(SELECT 1 FROM public.backload_items WHERE trip_line_item_id IN (SELECT id FROM public.trip_line_items WHERE trip_id=p_trip_id AND (v_last OR trip_stop_id=p_stop_id)) AND NOT(backload_id=ANY(v_backloads))) THEN
    RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='A retained report references this transaction line item.';
  END IF;
  FOR v_receipt IN SELECT * FROM public.report_receipts WHERE trip_id=p_trip_id AND (v_last OR trip_stop_id=p_stop_id) LOOP
    IF v_receipt.offload_id=ANY(v_offloads) THEN v_type:='offload'; v_id:=v_receipt.offload_id;
    ELSIF v_receipt.backload_id=ANY(v_backloads) THEN v_type:='backload'; v_id:=v_receipt.backload_id;
    ELSIF v_receipt.unloading_report_id=ANY(v_unloading) THEN v_type:='unloading'; v_id:=v_receipt.unloading_report_id;
    ELSIF v_receipt.loading_report_id=ANY(v_loading) THEN v_type:='loading'; v_id:=v_receipt.loading_report_id;
    ELSE RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='A receipt belongs to a retained/shared report.';
    END IF;
    v_prefix:='operations/'||p_trip_id||'/'||v_type||'/'||v_id||'/';
    IF v_receipt.storage_path IS NULL OR left(v_receipt.storage_path,length(v_prefix))<>v_prefix OR substring(v_receipt.storage_path from length(v_prefix)+1) !~ '^[a-f0-9-]{36}\.(jpg|jpeg|png|webp)$' THEN
      RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='Receipt storage ownership requires review.';
    END IF;
    v_objects:=v_objects||jsonb_build_array(jsonb_build_object('bucket','report-receipts','path',v_receipt.storage_path));
  END LOOP;
  IF v_last THEN
    FOR v_image IN SELECT * FROM public.trip_images WHERE trip_id=p_trip_id LOOP
      v_prefix:='trips/'||p_trip_id||'/';
      IF v_image.storage_path IS NULL OR left(v_image.storage_path,length(v_prefix))<>v_prefix OR substring(v_image.storage_path from length(v_prefix)+1) !~ '^[a-f0-9-]{36}\.(jpg|jpeg|png|webp)$' THEN
        RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='Trip image ownership requires review.';
      END IF;
      v_objects:=v_objects||jsonb_build_array(jsonb_build_object('bucket','trip-images','path',v_image.storage_path));
    END LOOP;
  END IF;
  IF EXISTS(SELECT 1 FROM public.documents d CROSS JOIN jsonb_array_elements(v_objects) o WHERE position(o->>'path' in coalesce(d.file_path,''))>0) THEN
    RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='An image is referenced by a retained document.';
  END IF;
  IF EXISTS(SELECT 1 FROM public.trip_images i CROSS JOIN jsonb_array_elements(v_objects) o WHERE i.storage_path=o->>'path' AND (i.trip_id<>p_trip_id OR NOT v_last))
    OR EXISTS(SELECT 1 FROM public.report_receipts r CROSS JOIN jsonb_array_elements(v_objects) o WHERE r.storage_path=o->>'path' AND NOT(r.trip_id=p_trip_id AND (v_last OR r.trip_stop_id=p_stop_id))) THEN
    RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='An image is also referenced by retained business data.';
  END IF;
  -- Protect exact objects also referenced by legacy driver history, including
  -- another trip. Never guess that a legacy URL/path is exclusively owned.
  IF EXISTS(SELECT FROM public.driver_trip_updates d CROSS JOIN jsonb_array_elements(v_objects) o
    WHERE (position(o->>'path' in coalesce(d.pod_image_path,''))>0
       OR position(o->>'path' in coalesce(d.pod_image_url,''))>0)
     AND NOT(v_last AND d.trip_id=p_trip_id AND EXISTS(SELECT FROM public.inspect_legacy_pod_ownership_v1(ARRAY[p_trip_id]) verified WHERE verified.update_id=d.id AND verified.status='VERIFIED'))) THEN
    RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='An image is referenced by retained driver history; ownership review is required.';
  END IF;
  -- Capture immutable Storage object IDs, not just names, before removing relations.
  SELECT coalesce(jsonb_agg(DISTINCT object || jsonb_build_object('object_id',s.id,'metadata_fingerprint',md5(coalesce(s.metadata::text,'')),'object_version',to_jsonb(s)->>'version')),'[]') INTO v_objects
   FROM jsonb_array_elements(v_objects) object LEFT JOIN storage.objects s ON s.bucket_id=object->>'bucket' AND s.name=object->>'path';
  IF EXISTS(SELECT FROM jsonb_array_elements(v_objects) object WHERE object->>'object_id' IS NULL) THEN
   RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='Storage object identity cannot be verified; nothing was deleted.';
  END IF;
  v_snapshot:=jsonb_build_object('trip',v_trip,'stop',v_stop,'parent_deleted',v_last,'actor_profile_id',p_actor_id,'legacy_pod_ownership',(SELECT coalesce(jsonb_agg(to_jsonb(r)),'[]') FROM public.inspect_legacy_pod_ownership_v1(ARRAY[p_trip_id]) r));
  -- Fixed allowlist only, never a client-supplied relation or predicate.
  FOREACH v_table IN ARRAY ARRAY['trip_line_items','trip_events','store_calls','documents','incidents','demurrages','pod_records','offloads','backloads','unloading_reports','report_receipts'] LOOP
    EXECUTE format('SELECT coalesce(jsonb_agg(to_jsonb(t)),''[]''::jsonb) FROM public.%I t WHERE trip_id=$1 AND ($3 OR trip_stop_id=$2)',v_table) INTO v_rows USING p_trip_id,p_stop_id,v_last;
    v_snapshot:=v_snapshot||jsonb_build_object(v_table,v_rows);
  END LOOP;
  SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]') INTO v_rows FROM public.offload_items t WHERE offload_id=ANY(v_offloads);
  v_snapshot:=v_snapshot||jsonb_build_object('offload_items',v_rows);
  SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]') INTO v_rows FROM public.backload_items t WHERE backload_id=ANY(v_backloads);
  v_snapshot:=v_snapshot||jsonb_build_object('backload_items',v_rows);
  SELECT coalesce(array_agg(id),'{}') INTO v_flex_ids FROM public.flex_rows WHERE row_kind='SOURCE' AND (
    (source_entity_type='STOP' AND source_entity_id=p_stop_id)
    OR (source_entity_type='TRIP' AND source_entity_id=p_trip_id AND v_last)
    OR (source_entity_type='LINE_ITEM' AND source_entity_id IN (SELECT id FROM public.trip_line_items WHERE trip_id=p_trip_id AND (v_last OR trip_stop_id=p_stop_id)))
    OR (source_entity_type='STORE_CALL' AND source_entity_id IN (SELECT id FROM public.store_calls WHERE trip_id=p_trip_id AND (v_last OR trip_stop_id=p_stop_id)))
    OR (source_entity_type='ASSIGNMENT' AND v_last AND source_entity_id IN (SELECT id FROM public.trip_truck_assignments WHERE trip_id=p_trip_id))
  );
  SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]') INTO v_rows FROM public.flex_rows t WHERE id=ANY(v_flex_ids);
  v_snapshot:=v_snapshot||jsonb_build_object('flex_rows',v_rows);
  SELECT coalesce(jsonb_agg(to_jsonb(c)),'[]') INTO v_rows FROM public.flex_cells c WHERE row_id=ANY(v_flex_ids);
  v_snapshot:=v_snapshot||jsonb_build_object('flex_cells',v_rows);
  IF v_last THEN
    SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]') INTO v_rows FROM public.trip_truck_assignments t WHERE trip_id=p_trip_id;
    v_snapshot:=v_snapshot||jsonb_build_object('assignments',v_rows);
    SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]') INTO v_rows FROM public.trip_images t WHERE trip_id=p_trip_id;
    v_snapshot:=v_snapshot||jsonb_build_object('trip_images',v_rows);
    SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]') INTO v_rows FROM public.loading_reports t WHERE trip_id=p_trip_id;
    v_snapshot:=v_snapshot||jsonb_build_object('loading_reports',v_rows);
  END IF;
  IF v_last THEN
    SELECT coalesce(jsonb_agg(id ORDER BY id),'[]'::jsonb) INTO v_rows FROM public.driver_trip_updates WHERE trip_id=p_trip_id;
    v_snapshot:=v_snapshot||jsonb_build_object('driver_update_cleanup',jsonb_build_object('ids',v_rows,'count',jsonb_array_length(v_rows)));
  END IF;
  INSERT INTO public.transaction_deletion_jobs(transaction_id,trip_id,trip_stop_id,requested_by,state,storage_objects,snapshot,completed_at)
    VALUES(coalesce(p_stop_id,p_trip_id),p_trip_id,p_stop_id,p_actor_id,CASE WHEN jsonb_array_length(v_objects)=0 THEN 'COMPLETE' ELSE 'PENDING_STORAGE' END,v_objects,v_snapshot,CASE WHEN jsonb_array_length(v_objects)=0 THEN now() END) RETURNING * INTO v_job;
  -- Immutable manifests and complete image snapshots were captured above under
  -- the same ownership/retention locks. Remove final-parent image relations now,
  -- before POD/stop ON DELETE SET NULL can trigger their journal reuse guard.
  -- Storage bytes remain untouched until the existing post-commit validator runs.
  -- Earlier stops keep their image relations exactly as before.
  IF v_last THEN DELETE FROM public.trip_images WHERE trip_id=p_trip_id; END IF;
  DELETE FROM public.report_receipts WHERE trip_id=p_trip_id AND (v_last OR trip_stop_id=p_stop_id);
  DELETE FROM public.offloads WHERE id=ANY(v_offloads);
  DELETE FROM public.backloads WHERE id=ANY(v_backloads);
  DELETE FROM public.unloading_reports WHERE id=ANY(v_unloading);
  DELETE FROM public.loading_reports WHERE id=ANY(v_loading);
  DELETE FROM public.flex_rows WHERE id=ANY(v_flex_ids);
  FOREACH v_table IN ARRAY ARRAY['incidents','demurrages','pod_records','documents','store_calls','trip_events','trip_line_items'] LOOP
    EXECUTE format('DELETE FROM public.%I WHERE trip_id=$1 AND ($3 OR trip_stop_id=$2)',v_table) USING p_trip_id,p_stop_id,v_last;
  END LOOP;
  DELETE FROM public.trip_stops WHERE id=p_stop_id AND trip_id=p_trip_id;
  IF v_last THEN
    -- Explicit eligible cleanup, not FK CASCADE. Any later failure restores
    -- updates, stops, reports and the private audit/Storage journal together.
    DELETE FROM public.driver_trip_updates WHERE trip_id=p_trip_id;
    DELETE FROM public.trips WHERE id=p_trip_id;
  END IF;
  RETURN to_jsonb(v_job);
END;
$function$
CREATE OR REPLACE FUNCTION public.can_read_admin_change_signals()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.profiles p
    JOIN public.admin_staff_session_days s ON s.profile_id=p.id AND s.role=p.role
    WHERE p.id=auth.uid() AND p.role IN ('ADMIN','STAFF') AND s.expires_at>now()
  );
$function$
CREATE OR REPLACE FUNCTION public.notify_admin_source_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  -- Only the trigger's table name is emitted. Old/new row contents are never read.
  INSERT INTO public.admin_change_signals(topic) VALUES(TG_TABLE_NAME)
    ON CONFLICT(topic) DO UPDATE SET revision=gen_random_uuid(),changed_at=clock_timestamp();
  RETURN NULL;
END;
$function$
CREATE OR REPLACE FUNCTION public.tracker_page_cells_v1(p_cells jsonb, p_count bigint, p_fields bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
 IF p_count<>p_fields THEN RAISE EXCEPTION USING ERRCODE='21000',MESSAGE='Ambiguous tracker field binding; repair metadata before paging.'; END IF;
 RETURN coalesce(p_cells,'{}'::jsonb);
END; $function$
CREATE OR REPLACE FUNCTION public.inspect_legacy_pod_ownership_v1(p_trip_ids uuid[])
 RETURNS TABLE(update_id uuid, trip_id uuid, image_id uuid, trip_stop_id uuid, storage_object_id uuid, storage_path text, status text, reason text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
 SELECT d.id,d.trip_id,i.id,i.trip_stop_id,o.id,d.pod_image_path,
 CASE WHEN issues.reason IS NULL THEN 'VERIFIED' ELSE 'BLOCKED' END,
 coalesce(issues.reason,'Exact receipt, stop, driver/uploader, assignment and private Storage metadata agree.')
 FROM public.driver_trip_updates d
 LEFT JOIN public.trip_images i ON i.storage_path=d.pod_image_path
 LEFT JOIN public.trip_stops s ON s.id=i.trip_stop_id
 LEFT JOIN public.pod_records p ON p.id=i.pod_record_id
 LEFT JOIN public.drivers dr ON dr.id=d.driver_id
 LEFT JOIN storage.objects o ON o.bucket_id='trip-images' AND o.name=i.storage_path
 LEFT JOIN storage.buckets b ON b.id=o.bucket_id
 CROSS JOIN LATERAL (SELECT CASE
  WHEN nullif(btrim(d.pod_image_url),'') IS NOT NULL THEN 'Legacy URL requires manual ownership review; it is not interpreted as a trusted Storage path.'
  WHEN nullif(btrim(d.pod_image_path),'') IS NULL THEN 'No canonical Storage path is recorded.'
  WHEN (SELECT count(*) FROM public.trip_images x WHERE x.storage_path=d.pod_image_path)<>1 THEN 'Receipt is missing or the path is shared by multiple receipt records.'
  WHEN i.trip_id IS DISTINCT FROM d.trip_id OR s.trip_id IS DISTINCT FROM d.trip_id THEN 'Receipt or stop does not belong to this parent trip.'
  WHEN i.kind IS DISTINCT FROM 'receipt' OR i.uploaded_by IS NULL OR i.uploaded_by IS DISTINCT FROM dr.profile_id THEN 'Authenticated receipt uploader and original driver do not match.'
  WHEN NOT EXISTS(SELECT FROM public.trip_truck_assignments a WHERE a.trip_id=d.trip_id AND a.driver_id=d.driver_id) THEN 'No matching driver/trip assignment establishes ownership.'
  WHEN i.pod_record_id IS NOT NULL AND (p.trip_id IS DISTINCT FROM i.trip_id OR p.trip_stop_id IS DISTINCT FROM i.trip_stop_id) THEN 'Linked POD belongs to another trip or stop.'
  WHEN o.id IS NULL OR b.public IS DISTINCT FROM false THEN 'Private Storage object is missing or bucket privacy cannot be verified.'
  WHEN o.owner_id IS NOT NULL AND o.owner_id IS DISTINCT FROM i.uploaded_by::text THEN 'Storage owner conflicts with the authenticated uploader.'
  WHEN o.metadata->>'mimetype' NOT IN ('image/jpeg','image/png','image/webp') OR o.metadata->>'mimetype' IS NULL THEN 'Storage MIME metadata is unsupported or missing; PDF retention needs separate review.'
  WHEN d.pod_image_path !~ ('^trips/'||d.trip_id||'/[a-f0-9-]{36}\.(jpg|jpeg|png|webp)$') THEN 'Receipt path is outside the supported immutable upload namespace.'
  WHEN EXISTS(SELECT FROM public.driver_trip_updates x WHERE x.trip_id IS DISTINCT FROM d.trip_id AND nullif(btrim(x.pod_image_url),'') IS NOT NULL) THEN 'Unresolved URL-only driver history elsewhere requires shared-object review.'
  WHEN EXISTS(SELECT FROM public.driver_trip_updates x WHERE x.trip_id IS DISTINCT FROM d.trip_id AND (x.pod_image_path=d.pod_image_path OR position(d.pod_image_path in coalesce(x.pod_image_url,''))>0)) THEN 'Another trip driver history references this object.'
  WHEN EXISTS(SELECT FROM public.report_receipts x WHERE x.storage_path=d.pod_image_path)
    OR EXISTS(SELECT FROM public.documents x WHERE position(d.pod_image_path in coalesce(x.file_path,''))>0)
    OR EXISTS(SELECT FROM public.pod_drive_files x WHERE position(d.pod_image_path in coalesce(x.drive_link,''))>0) THEN 'Document, report or Drive reference requires retention review.'
 END AS reason) issues
 WHERE d.trip_id=ANY(p_trip_ids) AND (nullif(btrim(d.pod_image_path),'') IS NOT NULL OR nullif(btrim(d.pod_image_url),'') IS NOT NULL)
$function$
CREATE OR REPLACE FUNCTION public.tracker_page_text_v1(p_value jsonb, p_fallback text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v jsonb:=p_value; parsed jsonb; n bigint;
BEGIN
 IF v IS NULL OR v='null'::jsonb THEN RETURN p_fallback; END IF;
 IF jsonb_typeof(v)='string' THEN
   BEGIN parsed:=(v#>>'{}')::jsonb; EXCEPTION WHEN invalid_text_representation THEN parsed:=NULL; END;
   IF jsonb_typeof(parsed)='object' AND jsonb_typeof(parsed->'__alzhen_transmittal_pod_values_v1')='object' THEN
     SELECT count(DISTINCT value),min(value::text)::jsonb INTO n,v
       FROM jsonb_each(parsed->'__alzhen_transmittal_pod_values_v1')
       WHERE value NOT IN ('null'::jsonb,'""'::jsonb);
     IF n>1 OR v IS NULL THEN RETURN p_fallback; END IF;
   END IF;
 END IF;
 IF v='{"__alzhen_tracker_empty_override_v1__":true}'::jsonb
   OR (jsonb_typeof(v)='object' AND v->'__alzhen_tracker_empty_override_v1__'='true'::jsonb) THEN RETURN ''; END IF;
 IF jsonb_typeof(v)='string' THEN RETURN v#>>'{}'; END IF;
 RETURN '';
END; $function$
CREATE OR REPLACE FUNCTION public.review_pod_receipt_v1(p_actor_id uuid, p_request_id uuid, p_trip_id uuid, p_stop_id uuid, p_receipt_id uuid, p_expected_review_version bigint, p_expected_ocr_version integer, p_decision text, p_reason text, p_reviewed_fields jsonb, p_pod_record_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
 r public.trip_images%ROWTYPE; s public.trip_stops%ROWTYPE;
 actor public.profiles%ROWTYPE; prior public.pod_review_events%ROWTYPE;
 pod public.pod_records%ROWTYPE; pod_id uuid; recipient uuid;
 event_id uuid:=gen_random_uuid(); notice_id uuid:=gen_random_uuid();
 result jsonb; dr text; ids uuid[]; field_key text;
BEGIN
 SELECT * INTO actor FROM public.profiles WHERE id=p_actor_id FOR SHARE;
 IF NOT FOUND OR actor.role NOT IN ('ADMIN','STAFF') THEN RAISE EXCEPTION 'POD review requires Admin or Staff.' USING ERRCODE='42501'; END IF;
 IF p_request_id IS NULL OR p_expected_review_version IS NULL OR p_expected_ocr_version IS NULL OR p_expected_review_version<0 OR p_expected_ocr_version<0
  OR p_decision IS NULL OR p_decision NOT IN ('APPROVED','REJECTED')
  OR p_reviewed_fields IS NULL OR jsonb_typeof(p_reviewed_fields)<>'object' OR octet_length(p_reviewed_fields::text)>16000
  OR length(coalesce(p_reason,''))>2000 OR (p_decision='REJECTED' AND btrim(coalesce(p_reason,''))='')
 THEN RAISE EXCEPTION 'Invalid POD decision, reason or review version.' USING ERRCODE='22023'; END IF;
 FOR field_key IN SELECT jsonb_object_keys(p_reviewed_fields) LOOP
  IF field_key NOT IN ('dr_number','dispatch_number','so_number','customer_name','store_name','delivery_date','receiving_date','receiver_name','quantity','product_information','document_references') THEN
   RAISE EXCEPTION 'Unsupported review field.' USING ERRCODE='22023';
  END IF;
 END LOOP;
 -- Serializes request-key reuse across receipts, then serializes physical review.
 PERFORM pg_advisory_xact_lock(hashtextextended(p_actor_id::text||':'||p_request_id::text,0));
 SELECT * INTO prior FROM public.pod_review_events WHERE actor_profile_id=p_actor_id AND request_id=p_request_id;
 IF FOUND THEN
  IF prior.receipt_id<>p_receipt_id OR prior.trip_id<>p_trip_id OR prior.trip_stop_id<>p_stop_id OR prior.decision<>p_decision
   OR prior.expected_review_version<>p_expected_review_version OR prior.expected_ocr_version<>p_expected_ocr_version
   OR prior.reason IS DISTINCT FROM nullif(btrim(coalesce(p_reason,'')),'') OR prior.reviewed_fields<>p_reviewed_fields
   OR (prior.outcome->>'requested_pod_record_id') IS DISTINCT FROM p_pod_record_id::text THEN
   RAISE EXCEPTION 'Request ID already belongs to a different decision.' USING ERRCODE='40001';
  END IF;
  RETURN prior.outcome;
 END IF;
 SELECT * INTO r FROM public.trip_images WHERE id=p_receipt_id AND trip_id=p_trip_id AND trip_stop_id=p_stop_id AND kind='receipt' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Receipt does not belong to this transaction.' USING ERRCODE='P0002'; END IF;
 IF r.pod_review_version<>p_expected_review_version OR r.ocr_version<>p_expected_ocr_version THEN RAISE EXCEPTION 'Receipt changed. Reload before deciding.' USING ERRCODE='40001'; END IF;
 IF r.pod_review_status='APPROVED' THEN RAISE EXCEPTION 'An approved document cannot be decided again.' USING ERRCODE='55000'; END IF;
 IF NOT EXISTS(SELECT 1 FROM storage.buckets WHERE id='trip-images' AND public=false) THEN
  RAISE EXCEPTION 'The original receipt bucket must be private.' USING ERRCODE='55000';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='trip-images' AND name=r.storage_path) THEN
  RAISE EXCEPTION 'The original receipt object is missing. Restore a verified document association before review.' USING ERRCODE='55000';
 END IF;
 SELECT * INTO s FROM public.trip_stops WHERE id=p_stop_id AND trip_id=p_trip_id AND archived_at IS NULL FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Active delivery transaction not found.' USING ERRCODE='P0002'; END IF;
 -- The uploader is the historical submitter; never trust a client recipient ID.
 SELECT id INTO recipient FROM public.profiles WHERE id=r.uploaded_by AND role='TRUCKER';
 IF recipient IS NULL THEN
  SELECT array_agg(d.profile_id) INTO ids FROM public.trip_truck_assignments a JOIN public.drivers d ON d.id=a.driver_id
   JOIN public.profiles p ON p.id=d.profile_id AND p.role='TRUCKER'
   WHERE a.trip_id=p_trip_id AND a.assignment_type='PRIMARY' AND a.unassigned_at IS NULL;
  IF cardinality(ids)=1 THEN recipient:=ids[1]; END IF;
 END IF;
 IF recipient IS NULL THEN RAISE EXCEPTION 'Responsible trucker is missing or ambiguous. Correct the assignment before review.' USING ERRCODE='55000'; END IF;
 IF p_decision='APPROVED' THEN
  dr:=coalesce(nullif(btrim(s.dr_number),''),nullif(btrim(r.dr_number),''));
  IF dr IS NULL THEN RAISE EXCEPTION 'Confirm the transaction DR number before approval.' USING ERRCODE='55000'; END IF;
  IF nullif(btrim(r.dr_number),'') IS NOT NULL AND regexp_replace(lower(r.dr_number),'[^a-z0-9]','','g')<>regexp_replace(lower(dr),'[^a-z0-9]','','g') THEN
   RAISE EXCEPTION 'Receipt DR differs from the saved transaction. Review the association.' USING ERRCODE='55000';
  END IF;
  IF nullif(btrim(p_reviewed_fields->>'dr_number'),'') IS NOT NULL AND regexp_replace(lower(p_reviewed_fields->>'dr_number'),'[^a-z0-9]','','g')<>regexp_replace(lower(dr),'[^a-z0-9]','','g') THEN
   RAISE EXCEPTION 'Reviewed DR differs from the saved transaction.' USING ERRCODE='55000';
  END IF;
  IF p_pod_record_id IS NOT NULL THEN
   SELECT * INTO pod FROM public.pod_records WHERE id=p_pod_record_id AND trip_id=p_trip_id AND trip_stop_id=p_stop_id FOR UPDATE;
   IF NOT FOUND OR regexp_replace(lower(coalesce(pod.dr_number,'')),'[^a-z0-9]','','g')<>regexp_replace(lower(dr),'[^a-z0-9]','','g') THEN
    RAISE EXCEPTION 'Selected POD does not match this transaction and DR.' USING ERRCODE='55000';
   END IF;
  ELSE
   SELECT array_agg(id) INTO ids FROM public.pod_records WHERE trip_id=p_trip_id AND trip_stop_id=p_stop_id;
   IF cardinality(ids)>1 THEN RAISE EXCEPTION 'Multiple historical POD records require an explicit matching POD ID.' USING ERRCODE='55000'; END IF;
   IF cardinality(ids)=1 THEN
    SELECT * INTO pod FROM public.pod_records WHERE id=ids[1] FOR UPDATE;
    IF regexp_replace(lower(coalesce(pod.dr_number,'')),'[^a-z0-9]','','g')<>regexp_replace(lower(dr),'[^a-z0-9]','','g') THEN
     RAISE EXCEPTION 'Historical POD DR differs. Review the record before approval.' USING ERRCODE='55000';
    END IF;
   END IF;
  END IF;
  IF pod.id IS NULL THEN
   INSERT INTO public.pod_records(trip_id,trip_stop_id,dr_number,pod_status,pod_received_at)
    VALUES(p_trip_id,p_stop_id,dr,'RECEIVED',clock_timestamp()) RETURNING id INTO pod_id;
  ELSE
   pod_id:=pod.id;
   UPDATE public.pod_records SET pod_status=CASE WHEN pod_status='PENDING_TRUCKER_CONFIRMATION' THEN 'RECEIVED' ELSE pod_status END,
    pod_received_at=coalesce(pod_received_at,clock_timestamp()) WHERE id=pod_id;
  END IF;
 END IF;
 UPDATE public.trip_images SET pod_review_status=p_decision,pod_review_version=pod_review_version+1,
  pod_reviewed_by=p_actor_id,pod_reviewed_at=clock_timestamp(),pod_rejection_reason=CASE WHEN p_decision='REJECTED' THEN btrim(p_reason) END,
  pod_record_id=coalesce(pod_id,pod_record_id),updated_at=clock_timestamp() WHERE id=r.id;
 result:=jsonb_build_object('event_id',event_id,'request_id',p_request_id,'receipt_id',r.id,'trip_id',p_trip_id,'trip_stop_id',p_stop_id,
  'status',p_decision,'review_version',r.pod_review_version+1,'pod_record_id',pod_id,'notification_id',notice_id,'requested_pod_record_id',p_pod_record_id);
 INSERT INTO public.admin_notifications(id,recipient_profile_id,actor_profile_id,notification_type,reference_type,reference_id,message,metadata,event_key)
  VALUES(notice_id,recipient,p_actor_id,CASE WHEN p_decision='APPROVED' THEN 'pod_approved' ELSE 'pod_rejected' END,'trip',p_trip_id,
   CASE WHEN p_decision='APPROVED' THEN 'Your POD was approved.' ELSE 'Your POD was rejected: '||btrim(p_reason) END,
   jsonb_build_object('trip_id',p_trip_id,'trip_stop_id',p_stop_id,'receipt_id',r.id,'review_status',p_decision),event_id);
 INSERT INTO public.pod_review_events(id,request_id,actor_profile_id,actor_snapshot,receipt_id,trip_id,trip_stop_id,decision,reason,reviewed_fields,expected_review_version,expected_ocr_version,outcome)
  VALUES(event_id,p_request_id,p_actor_id,concat_ws(' ',actor.first_name,actor.last_name),r.id,p_trip_id,p_stop_id,p_decision,nullif(btrim(coalesce(p_reason,'')),''),p_reviewed_fields,p_expected_review_version,p_expected_ocr_version,result);
 RETURN result;
END $function$
CREATE OR REPLACE FUNCTION public.bump_collaboration_version_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
 NEW.collaboration_version := OLD.collaboration_version + 1;
 RETURN NEW;
END;
$function$
CREATE OR REPLACE FUNCTION public.operations_natural_sort_v1(p_value text)
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE STRICT
 SET search_path TO 'pg_catalog'
AS $function$
 SELECT ARRAY(SELECT CASE WHEN token[1] ~ '^[0-9]+$'
   THEN '0'||lpad(length(ltrim(token[1],'0'))::text,10,'0')||ltrim(token[1],'0')
   ELSE '1'||token[1] END
 FROM regexp_matches(lower(p_value),'[0-9]+|[^0-9]+','g') WITH ORDINALITY AS chunks(token,n)
 ORDER BY n)
$function$
CREATE OR REPLACE FUNCTION public.tracking_feed_v1(p_actor uuid, p_after uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE result jsonb;
BEGIN
 IF NOT EXISTS(SELECT FROM public.profiles WHERE id=p_actor AND role IN ('ADMIN','STAFF')) THEN
  RAISE EXCEPTION 'Management tracking access required.' USING ERRCODE='42501'; END IF;
 IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 50 THEN RAISE EXCEPTION 'Invalid tracking page size.' USING ERRCODE='22023'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('context',public.tracking_route_context_v1(page.id,false),'cache',to_jsonb(r)) ORDER BY page.id),'[]'::jsonb)
 INTO result FROM (SELECT a.id FROM public.trip_truck_assignments a JOIN public.trips t ON t.id=a.trip_id
  JOIN public.trip_tracking_locations l ON l.assignment_id=a.id AND l.enabled AND l.captured_at IS NOT NULL
  JOIN public.drivers d ON d.id=a.driver_id AND d.profile_id=l.profile_id
  WHERE a.unassigned_at IS NULL AND t.archived_at IS NULL AND t.status NOT IN ('COMPLETED','CANCELLED')
   AND (p_after IS NULL OR a.id>p_after) ORDER BY a.id LIMIT p_limit+1) page
 LEFT JOIN public.trip_route_cache r ON r.assignment_id=page.id;
 RETURN result;
END $function$
CREATE OR REPLACE FUNCTION public.check_backload_receipt_capacity_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
 IF NEW.backload_id IS NULL THEN RETURN NEW; END IF;
 IF TG_OP='UPDATE' AND OLD.backload_id IS NOT DISTINCT FROM NEW.backload_id THEN RETURN NEW; END IF;
 PERFORM id FROM public.backloads WHERE id=NEW.backload_id FOR UPDATE;
 IF (SELECT count(*) FROM public.report_receipts WHERE backload_id=NEW.backload_id AND id<>NEW.id)>=20 THEN
  RAISE EXCEPTION 'A Backload supports at most twenty images.' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $function$
CREATE OR REPLACE FUNCTION public.guard_pending_operations_receipt_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
 IF OLD.upload_status='PENDING' AND (TG_OP='DELETE' OR NEW.trip_id IS DISTINCT FROM OLD.trip_id
  OR NEW.trip_stop_id IS DISTINCT FROM OLD.trip_stop_id OR NEW.offload_id IS DISTINCT FROM OLD.offload_id
  OR NEW.backload_id IS DISTINCT FROM OLD.backload_id) THEN
  RAISE EXCEPTION 'An image upload is incomplete. Retry the original upload before deleting or converting this report.' USING ERRCODE='55000';
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END $function$
CREATE OR REPLACE FUNCTION public.preview_whole_trip_deletion_v1(p_trip_ids uuid[], p_actor_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE trips_json jsonb; counts jsonb:='{}'; blockers jsonb:='[]'; relation text; n bigint; flex_ids uuid[];
BEGIN
 IF NOT EXISTS(SELECT FROM public.profiles WHERE id=p_actor_id AND role='ADMIN') THEN
  RAISE EXCEPTION 'Only ADMIN may preview whole-trip deletion.' USING ERRCODE='42501'; END IF;
 IF p_trip_ids IS NULL OR cardinality(p_trip_ids) NOT BETWEEN 1 AND 20 OR array_position(p_trip_ids,NULL) IS NOT NULL THEN
  RAISE EXCEPTION 'Select one to twenty physical trip IDs.' USING ERRCODE='22023'; END IF;
 SELECT jsonb_agg(jsonb_build_object('id',id,'dispatch_number',dispatch_number) ORDER BY id)
 INTO trips_json FROM public.trips WHERE id=ANY(p_trip_ids);
 IF coalesce(jsonb_array_length(trips_json),0)<>(SELECT count(DISTINCT id) FROM unnest(p_trip_ids) id) THEN
  RAISE EXCEPTION 'One or more selected trips no longer exists.' USING ERRCODE='P0002'; END IF;
 FOREACH relation IN ARRAY ARRAY['trip_stops','trip_line_items','trip_truck_assignments',
   'pod_records','trip_images','offloads','backloads','loading_reports','unloading_reports',
   'report_receipts','billings','payables','receivables','documents','pod_drive_files',
   'operations_report_conversions','incidents','store_calls','demurrages','trip_events','driver_trip_updates'] LOOP
  EXECUTE format('SELECT count(*) FROM public.%I WHERE trip_id=ANY($1)',relation) INTO n USING p_trip_ids;
  counts:=counts||jsonb_build_object(relation,n);
 END LOOP;
 SELECT count(*) INTO n FROM public.offload_items i JOIN public.offloads r ON r.id=i.offload_id WHERE r.trip_id=ANY(p_trip_ids);
 counts:=counts||jsonb_build_object('offload_items',n);
 SELECT count(*) INTO n FROM public.backload_items i JOIN public.backloads r ON r.id=i.backload_id WHERE r.trip_id=ANY(p_trip_ids);
 counts:=counts||jsonb_build_object('backload_items',n);
 SELECT count(*) INTO n FROM public.trip_tracking_locations l JOIN public.trip_truck_assignments a ON a.id=l.assignment_id WHERE a.trip_id=ANY(p_trip_ids);
 counts:=counts||jsonb_build_object('tracking_locations',n);
 SELECT count(*) INTO n FROM public.trip_route_cache c JOIN public.trip_truck_assignments a ON a.id=c.assignment_id WHERE a.trip_id=ANY(p_trip_ids);
 counts:=counts||jsonb_build_object('cached_routes',n);
 SELECT coalesce(array_agg(f.id),'{}') INTO flex_ids FROM public.flex_rows f WHERE row_kind='SOURCE' AND (
  (source_entity_type='TRIP' AND source_entity_id=ANY(p_trip_ids)) OR
  (source_entity_type='STOP' AND source_entity_id IN (SELECT id FROM public.trip_stops WHERE trip_id=ANY(p_trip_ids))) OR
  (source_entity_type='LINE_ITEM' AND source_entity_id IN (SELECT id FROM public.trip_line_items WHERE trip_id=ANY(p_trip_ids))) OR
  (source_entity_type='STORE_CALL' AND source_entity_id IN (SELECT id FROM public.store_calls WHERE trip_id=ANY(p_trip_ids))) OR
  (source_entity_type='ASSIGNMENT' AND source_entity_id IN (SELECT id FROM public.trip_truck_assignments WHERE trip_id=ANY(p_trip_ids))));
 counts:=counts||jsonb_build_object('source_flex_rows',cardinality(flex_ids));
 SELECT count(*) INTO n FROM public.flex_cells WHERE row_id=ANY(flex_ids);
 counts:=counts||jsonb_build_object('source_flex_cells',n);
 SELECT count(*) INTO n FROM public.pod_review_events WHERE trip_id=ANY(p_trip_ids);
 counts:=counts||jsonb_build_object('pod_review_events_retained',n);
 IF (counts->>'billings')::bigint+(counts->>'payables')::bigint+(counts->>'receivables')::bigint>0 THEN
  blockers:=blockers||jsonb_build_array('Billing, payable or receivable records require accounting retention review.'); END IF;
 IF (counts->>'operations_report_conversions')::bigint>0 THEN
  blockers:=blockers||jsonb_build_array('Protected report conversion history prevents deletion.'); END IF;
 IF EXISTS(SELECT FROM public.documents WHERE trip_id=ANY(p_trip_ids) AND nullif(btrim(file_path),'') IS NOT NULL)
    OR (counts->>'pod_drive_files')::bigint>0 THEN
  blockers:=blockers||jsonb_build_array('Document or Drive attachments require an ownership/retention review.'); END IF;
 IF EXISTS(SELECT FROM public.inspect_legacy_pod_ownership_v1(p_trip_ids) WHERE status='BLOCKED') THEN
  blockers:=blockers||jsonb_build_array('Legacy POD ownership or retention is unresolved. Review the exact attachment findings below.'); END IF;
 IF EXISTS(SELECT FROM public.report_receipts WHERE trip_id=ANY(p_trip_ids) AND upload_status='PENDING') THEN
  blockers:=blockers||jsonb_build_array('An image upload is incomplete. Recover the original upload before deleting this trip.'); END IF;
 counts:=counts||jsonb_build_object('legacy_pod_references',(SELECT count(DISTINCT update_id) FROM public.inspect_legacy_pod_ownership_v1(p_trip_ids)),
  'storage_objects',(SELECT count(*) FROM (SELECT 'trip-images' AS bucket,storage_path FROM public.trip_images WHERE trip_id=ANY(p_trip_ids) UNION SELECT 'report-receipts',storage_path FROM public.report_receipts WHERE trip_id=ANY(p_trip_ids)) objects),
  'pending_uploads',(SELECT count(*) FROM public.report_receipts WHERE trip_id=ANY(p_trip_ids) AND upload_status='PENDING'));
 IF EXISTS(SELECT FROM storage.objects o CROSS JOIN unnest(p_trip_ids) selected_trip
 WHERE ((o.bucket_id='trip-images' AND left(o.name,length('trips/'||selected_trip||'/'))='trips/'||selected_trip||'/' AND NOT EXISTS(SELECT FROM public.trip_images i WHERE i.trip_id=selected_trip AND i.storage_path=o.name))
 OR (o.bucket_id='report-receipts' AND left(o.name,length('operations/'||selected_trip||'/'))='operations/'||selected_trip||'/' AND NOT EXISTS(SELECT FROM public.report_receipts r WHERE r.trip_id=selected_trip AND r.storage_path=o.name)))
 AND NOT EXISTS(SELECT FROM public.transaction_deletion_jobs j CROSS JOIN LATERAL jsonb_array_elements(j.storage_objects) manifest WHERE j.trip_id=selected_trip AND manifest->>'bucket'=o.bucket_id AND manifest->>'path'=o.name AND manifest->>'object_id'=o.id::text AND manifest->>'metadata_fingerprint'=md5(coalesce(o.metadata::text,'')) AND manifest->>'object_version' IS NOT DISTINCT FROM to_jsonb(o)->>'version')) THEN blockers:=blockers||jsonb_build_array('Unregistered Storage objects in a selected trip namespace require ownership review.'); END IF;
 IF EXISTS(SELECT FROM public.trip_images i WHERE i.trip_id=ANY(p_trip_ids) AND NOT EXISTS(SELECT FROM storage.objects o WHERE o.bucket_id='trip-images' AND o.name=i.storage_path)) THEN blockers:=blockers||jsonb_build_array('A receipt upload is incomplete or its private object is missing.'); END IF;
 -- Exact Storage paths and all ownership/retention guards are rechecked under
 -- locks during deletion. Preview never authorizes deletion on its own.
 RETURN jsonb_build_object('trips',trips_json,'counts',counts,'blockers',blockers,'attachment_review',(SELECT coalesce(jsonb_agg(to_jsonb(r)),'[]') FROM public.inspect_legacy_pod_ownership_v1(p_trip_ids) r));
END $function$
CREATE OR REPLACE FUNCTION public.delete_whole_trips_v1(p_trip_ids uuid[], p_actor_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE trip uuid; stop uuid; had_stops boolean; jobs jsonb; audit jsonb; job jsonb; legacy_evidence jsonb;
BEGIN
 IF NOT EXISTS(SELECT FROM public.profiles WHERE id=p_actor_id AND role='ADMIN') THEN
  RAISE EXCEPTION 'Only ADMIN may permanently delete whole trips.' USING ERRCODE='42501'; END IF;
 IF p_trip_ids IS NULL OR cardinality(p_trip_ids) NOT BETWEEN 1 AND 20 OR array_position(p_trip_ids,NULL) IS NOT NULL THEN
  RAISE EXCEPTION 'Select one to twenty physical trip IDs.' USING ERRCODE='22023'; END IF;
 -- Match the existing RPC's lock ordering. No independent stop delete requests:
 -- any error in any trip rolls back ALL calls and their audit/cleanup jobs.
 PERFORM set_config('lock_timeout','3s',true);
 LOCK TABLE public.trips,public.trip_stops,public.trip_line_items,
    public.trip_truck_assignments,public.trip_events,public.store_calls,
    public.documents,public.incidents,public.demurrages,public.billings,
    public.payables,public.receivables,public.pod_records,public.pod_drive_files,
    public.trip_images,public.offloads,public.offload_items,public.backloads,
    public.backload_items,public.loading_reports,public.unloading_reports,
    public.report_receipts,public.operations_report_conversions,
    public.flex_rows,public.flex_cells,public.driver_trip_updates IN SHARE ROW EXCLUSIVE MODE;
 IF EXISTS(SELECT FROM public.inspect_legacy_pod_ownership_v1(p_trip_ids) WHERE status='BLOCKED') THEN
  RAISE EXCEPTION 'Legacy POD ownership/retention is unresolved; inspect the attachment review. Nothing was deleted.' USING ERRCODE='55000'; END IF;
 IF EXISTS(SELECT FROM storage.objects o CROSS JOIN unnest(p_trip_ids) selected_trip
 WHERE ((o.bucket_id='trip-images' AND left(o.name,length('trips/'||selected_trip||'/'))='trips/'||selected_trip||'/' AND NOT EXISTS(SELECT FROM public.trip_images i WHERE i.trip_id=selected_trip AND i.storage_path=o.name))
 OR (o.bucket_id='report-receipts' AND left(o.name,length('operations/'||selected_trip||'/'))='operations/'||selected_trip||'/' AND NOT EXISTS(SELECT FROM public.report_receipts r WHERE r.trip_id=selected_trip AND r.storage_path=o.name)))
 AND NOT EXISTS(SELECT FROM public.transaction_deletion_jobs j CROSS JOIN LATERAL jsonb_array_elements(j.storage_objects) manifest WHERE j.trip_id=selected_trip AND manifest->>'bucket'=o.bucket_id AND manifest->>'path'=o.name AND manifest->>'object_id'=o.id::text AND manifest->>'metadata_fingerprint'=md5(coalesce(o.metadata::text,'')) AND manifest->>'object_version' IS NOT DISTINCT FROM to_jsonb(o)->>'version')) THEN RAISE EXCEPTION 'Unregistered Storage objects require ownership review; nothing was deleted.' USING ERRCODE='55000'; END IF;
 -- Independent legacy image/POD FKs do not enforce composite ownership.
 IF EXISTS(SELECT FROM public.trip_images i LEFT JOIN public.pod_records p ON p.id=i.pod_record_id
   LEFT JOIN public.trip_stops s ON s.id=i.trip_stop_id
   WHERE (i.trip_id=ANY(p_trip_ids) OR p.trip_id=ANY(p_trip_ids) OR s.trip_id=ANY(p_trip_ids))
     AND ((i.trip_stop_id IS NOT NULL AND s.trip_id IS DISTINCT FROM i.trip_id)
       OR (i.pod_record_id IS NOT NULL AND (p.trip_id IS DISTINCT FROM i.trip_id OR p.trip_stop_id IS DISTINCT FROM i.trip_stop_id)))) THEN
   RAISE EXCEPTION 'Image trip/stop/POD ownership is inconsistent; nothing was deleted.' USING ERRCODE='55000';
 END IF;
 FOR trip IN SELECT DISTINCT id FROM unnest(p_trip_ids) id ORDER BY id LOOP
  IF NOT EXISTS(SELECT FROM public.trips WHERE id=trip) THEN
   IF NOT EXISTS(SELECT FROM public.transaction_deletion_jobs WHERE trip_id=trip) THEN
    RAISE EXCEPTION 'Trip does not exist and no matching deletion operation is recorded.' USING ERRCODE='P0002';
   END IF;
   CONTINUE;
  END IF;
  SELECT coalesce(jsonb_agg(to_jsonb(r)),'[]') INTO legacy_evidence FROM public.inspect_legacy_pod_ownership_v1(ARRAY[trip]) r;
  audit:=public.preview_whole_trip_deletion_v1(ARRAY[trip],p_actor_id);
  audit:=jsonb_build_object('actor_id',p_actor_id,'trip_ids',to_jsonb(p_trip_ids),
    'trip_id',trip,'dispatch_number',audit->'trips'->0->'dispatch_number',
    'affected_counts',audit->'counts','legacy_pod_ownership',legacy_evidence,'deleted_at',transaction_timestamp(),'result','DATABASE_COMMITTED');
  -- The shared transaction RPC resolves eligible driver updates on the last
  -- stop and records their IDs in its private cleanup journal.
  -- Ownership was checked with all original stops/PODs intact. Remove only the
  -- verified attachment-bearing history now; retain evidence in every trip journal.
  -- Later failure in any trip rolls these removals back with the entire batch.
  DELETE FROM public.driver_trip_updates WHERE trip_id=trip AND id IN (SELECT (r->>'update_id')::uuid FROM jsonb_array_elements(legacy_evidence) r);
  had_stops:=false;
  FOR stop IN SELECT id FROM public.trip_stops WHERE trip_id=trip ORDER BY id LOOP
   had_stops:=true;
   job:=public.delete_transaction_with_cleanup_v1(trip,stop,p_actor_id);
   UPDATE public.transaction_deletion_jobs SET snapshot=snapshot||jsonb_build_object('whole_trip_deletion',audit)
    WHERE id=(job->>'id')::uuid AND NOT(snapshot ? 'whole_trip_deletion');
  END LOOP;
  IF NOT had_stops THEN
   job:=public.delete_transaction_with_cleanup_v1(trip,NULL,p_actor_id);
   UPDATE public.transaction_deletion_jobs SET snapshot=snapshot||jsonb_build_object('whole_trip_deletion',audit)
    WHERE id=(job->>'id')::uuid AND NOT(snapshot ? 'whole_trip_deletion');
  END IF;
  IF EXISTS(SELECT FROM public.trips WHERE id=trip) THEN RAISE EXCEPTION 'Parent deletion was not confirmed.' USING ERRCODE='55000'; END IF;
 END LOOP;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',j.id,'trip_id',j.trip_id,'trip_stop_id',j.trip_stop_id,'state',j.state) ORDER BY j.created_at,j.id),'[]') INTO jobs FROM public.transaction_deletion_jobs j WHERE j.trip_id=ANY(p_trip_ids);
 RETURN jobs;
END $function$
CREATE OR REPLACE FUNCTION public.delete_backload_with_cleanup_v1(p_backload_id uuid, p_actor_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_report public.backloads%ROWTYPE;
  v_job public.backload_deletion_jobs%ROWTYPE;
  v_receipts jsonb;
  v_items jsonb;
  v_paths text[];
  v_prefix text;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id=p_actor_id AND role IN ('ADMIN','STAFF')) THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='Only ADMIN or STAFF may delete Backload reports.';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('backload_delete:'||p_backload_id::text,0));
  SELECT * INTO v_job FROM public.backload_deletion_jobs WHERE backload_id=p_backload_id;
  IF FOUND THEN RETURN to_jsonb(v_job); END IF;
  SELECT * INTO v_report FROM public.backloads WHERE id=p_backload_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002', MESSAGE='Backload report not found.'; END IF;
  IF EXISTS (SELECT 1 FROM public.operations_report_conversions WHERE
    (source_type='BACKLOAD' AND source_id=p_backload_id) OR (target_type='BACKLOAD' AND target_id=p_backload_id)) THEN
    RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='This report is protected by conversion history.';
  END IF;
  -- Parent lock matches receipt/conversion writers. New receipt writes cannot
  -- attach after the deletion; failed uploads retain existing compensation.
  PERFORM id FROM public.report_receipts WHERE backload_id=p_backload_id FOR UPDATE;
  SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY id),'[]'::jsonb), coalesce(array_agg(storage_path ORDER BY id),'{}'::text[])
    INTO v_receipts,v_paths FROM public.report_receipts r WHERE backload_id=p_backload_id;
  v_prefix := 'operations/'||v_report.trip_id::text||'/backload/'||p_backload_id::text||'/';
  IF EXISTS (SELECT 1 FROM unnest(v_paths) p WHERE
      p IS NULL OR left(p,length(v_prefix))<>v_prefix OR substring(p from length(v_prefix)+1) !~ '^[a-f0-9-]{36}\.(jpg|jpeg|png|webp)$') THEN
    RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='Receipt storage ownership requires review; nothing was deleted.';
  END IF;
  IF EXISTS (SELECT 1 FROM public.report_receipts r WHERE r.backload_id IS DISTINCT FROM p_backload_id AND r.storage_path=ANY(v_paths)) THEN
    RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='Receipt is shared by another report; nothing was deleted.';
  END IF;
  IF EXISTS (SELECT 1 FROM public.documents d CROSS JOIN unnest(v_paths) p WHERE position(p in coalesce(d.file_path,''))>0) THEN
    RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='A receipt is referenced by a retained document; nothing was deleted.';
  END IF;
  PERFORM id FROM public.backload_items WHERE backload_id=p_backload_id FOR UPDATE;
  SELECT coalesce(jsonb_agg(to_jsonb(i) ORDER BY id),'[]'::jsonb) INTO v_items FROM public.backload_items i WHERE backload_id=p_backload_id;
  INSERT INTO public.backload_deletion_jobs(backload_id,trip_id,trip_stop_id,requested_by,state,storage_paths,snapshot,completed_at)
    VALUES(p_backload_id,v_report.trip_id,v_report.trip_stop_id,p_actor_id,
      CASE WHEN cardinality(v_paths)=0 THEN 'COMPLETE' ELSE 'PENDING_STORAGE' END,v_paths,
      jsonb_build_object('actor_profile_id',p_actor_id,'report',to_jsonb(v_report),'items',v_items,'receipts',v_receipts),
      CASE WHEN cardinality(v_paths)=0 THEN now() ELSE NULL END) RETURNING * INTO v_job;
  DELETE FROM public.report_receipts WHERE backload_id=p_backload_id;
  DELETE FROM public.backloads WHERE id=p_backload_id;
  -- Existing FK cascades delete only this Backload's item rows. No trip, stop,
  -- assignment, document, conversion record or other report is selected.
  RETURN to_jsonb(v_job);
END;
$function$
CREATE OR REPLACE FUNCTION public.submit_operations_report_v1(p_actor uuid, p_request uuid, p_type text, p_payload jsonb, p_report jsonb, p_item jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE prior public.operations_submission_requests; result jsonb; trip uuid; stop uuid;
BEGIN
 IF p_actor IS NULL OR p_request IS NULL OR p_type IS NULL OR p_type NOT IN ('OFFLOAD','BACKLOAD')
  OR p_payload IS NULL OR jsonb_typeof(p_payload)<>'object' OR octet_length(p_payload::text)>20000
  OR btrim(coalesce(p_report->>'reason',''))='' OR length(p_report->>'reason')>2000
 THEN RAISE EXCEPTION 'Invalid submission.' USING ERRCODE='22023'; END IF;
 trip:=(p_report->>'trip_id')::uuid; stop:=(p_report->>'trip_stop_id')::uuid;
 PERFORM public.lock_operations_submission_scope_v1(p_actor,trip,stop);
 PERFORM pg_advisory_xact_lock(hashtextextended('operations-submit:'||p_actor::text||':'||p_request::text,0));
 SELECT * INTO prior FROM public.operations_submission_requests WHERE actor_id=p_actor AND request_id=p_request;
 IF FOUND THEN
  IF prior.source_type<>p_type OR prior.request_payload<>p_payload THEN
   RAISE EXCEPTION 'Submission request was already used for different content.' USING ERRCODE='40001';
  END IF;
  -- Never recreate a report after explicit deletion or conversion.
  IF p_type='OFFLOAD' THEN PERFORM id FROM public.offloads WHERE id=(prior.outcome->>'id')::uuid;
  ELSE PERFORM id FROM public.backloads WHERE id=(prior.outcome->>'id')::uuid; END IF;
  IF NOT FOUND THEN RAISE EXCEPTION 'Previously submitted report is no longer available.' USING ERRCODE='55000'; END IF;
  RETURN prior.outcome;
 END IF;
 IF p_type='OFFLOAD' THEN
  IF stop IS NULL OR NOT EXISTS(SELECT 1 FROM public.trip_stops WHERE id=stop AND btrim(coalesce(dr_number,''))<>'') THEN
   RAISE EXCEPTION 'Select an exact DR transaction.' USING ERRCODE='23514';
  END IF;
  result:=public.create_offload_with_item_v1(p_report||jsonb_build_object('created_by',p_actor,'submitted_by',p_actor),p_item);
 ELSE
  INSERT INTO public.backloads(trip_id,trip_stop_id,reason,number_of_boxes,comments,created_by,submitted_by,submitted_at,event_type)
   VALUES(trip,stop,p_report->>'reason',(p_report->>'number_of_boxes')::numeric,p_report->>'comments',p_actor,p_actor,clock_timestamp(),'Backload')
   RETURNING to_jsonb(backloads.*) INTO result;
 END IF;
 INSERT INTO public.operations_submission_requests(actor_id,request_id,source_type,request_payload,outcome)
  VALUES(p_actor,p_request,p_type,p_payload,result);
 RETURN result;
END $function$
CREATE OR REPLACE FUNCTION public.reserve_operations_receipt_v1(p_actor uuid, p_request uuid, p_type text, p_record uuid, p_name text, p_mime text, p_size bigint, p_sha256 text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE parent record; saved public.report_receipts; path text; ext text;
BEGIN
 IF p_actor IS NULL OR p_request IS NULL OR p_type IS NULL OR p_type NOT IN ('OFFLOAD','BACKLOAD')
  OR p_name IS NULL OR length(p_name)>255 OR length(p_name)=0
  OR p_size IS NULL OR p_size NOT BETWEEN 1 AND 5242880 OR p_sha256 IS NULL OR p_sha256 !~ '^[a-f0-9]{64}$'
  OR p_mime IS NULL OR p_mime NOT IN ('image/jpeg','image/png','image/webp') THEN
  RAISE EXCEPTION 'Invalid image reservation.' USING ERRCODE='22023';
 END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('operations-upload:'||p_actor::text||':'||p_request::text,0));
 IF p_type='OFFLOAD' THEN SELECT id,trip_id,trip_stop_id INTO parent FROM public.offloads WHERE id=p_record FOR UPDATE;
 ELSE SELECT id,trip_id,trip_stop_id INTO parent FROM public.backloads WHERE id=p_record FOR UPDATE; END IF;
 IF NOT FOUND THEN RAISE EXCEPTION 'Report not found.' USING ERRCODE='P0002'; END IF;
 PERFORM public.lock_operations_submission_scope_v1(p_actor,parent.trip_id,parent.trip_stop_id);
 SELECT * INTO saved FROM public.report_receipts WHERE uploaded_by=p_actor AND upload_request_id=p_request;
 IF FOUND THEN
  IF coalesce(saved.offload_id,saved.backload_id)<>p_record OR (p_type='OFFLOAD')<>(saved.offload_id IS NOT NULL)
   OR saved.file_name<>p_name OR saved.mime_type<>p_mime OR saved.file_size_bytes<>p_size OR saved.upload_sha256<>p_sha256 THEN
   RAISE EXCEPTION 'Image request was already used for different content.' USING ERRCODE='40001';
  END IF;
  RETURN to_jsonb(saved);
 END IF;
 ext:=CASE p_mime WHEN 'image/jpeg' THEN 'jpg' WHEN 'image/png' THEN 'png' ELSE 'webp' END;
 -- Keep the installed deletion RPC's UUID filename ownership contract.
 path:='operations/'||parent.trip_id::text||'/'||lower(p_type)||'/'||p_record::text||'/'||gen_random_uuid()::text||'.'||ext;
 INSERT INTO public.report_receipts(trip_id,trip_stop_id,offload_id,backload_id,storage_path,file_name,mime_type,file_size_bytes,uploaded_by,upload_request_id,upload_sha256,upload_status)
  VALUES(parent.trip_id,parent.trip_stop_id,CASE WHEN p_type='OFFLOAD' THEN p_record END,CASE WHEN p_type='BACKLOAD' THEN p_record END,path,p_name,p_mime,p_size,p_actor,p_request,p_sha256,'PENDING')
  RETURNING * INTO saved;
 RETURN to_jsonb(saved);
END $function$
CREATE OR REPLACE FUNCTION public.complete_operations_receipt_v1(p_actor uuid, p_request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE r public.report_receipts;
BEGIN
 SELECT * INTO r FROM public.report_receipts WHERE uploaded_by=p_actor AND upload_request_id=p_request;
 IF NOT FOUND THEN RAISE EXCEPTION 'Image reservation not found.' USING ERRCODE='P0002'; END IF;
 IF r.offload_id IS NOT NULL THEN PERFORM id FROM public.offloads WHERE id=r.offload_id FOR UPDATE;
 ELSE PERFORM id FROM public.backloads WHERE id=r.backload_id FOR UPDATE; END IF;
 PERFORM public.lock_operations_submission_scope_v1(p_actor,r.trip_id,r.trip_stop_id);
 IF NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='report-receipts' AND name=r.storage_path) THEN
  RAISE EXCEPTION 'Image bytes are not yet available. Retry this upload.' USING ERRCODE='55000';
 END IF;
 UPDATE public.report_receipts SET upload_status='READY',received_at=coalesce(received_at,clock_timestamp())
  WHERE id=r.id RETURNING * INTO r;
 RETURN to_jsonb(r);
END $function$
CREATE OR REPLACE FUNCTION public.lock_operations_submission_scope_v1(p_actor uuid, p_trip uuid, p_stop uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE actor_role text; trip_status text;
BEGIN
 SELECT role INTO actor_role FROM public.profiles WHERE id=p_actor FOR SHARE;
 IF actor_role IS NULL OR actor_role NOT IN ('ADMIN','STAFF','TRUCKER') THEN
  RAISE EXCEPTION 'Reporting is not authorized.' USING ERRCODE='42501';
 END IF;
 SELECT status::text INTO trip_status FROM public.trips WHERE id=p_trip AND archived_at IS NULL FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Trip unavailable.' USING ERRCODE='P0002'; END IF;
 IF p_stop IS NOT NULL THEN
  PERFORM id FROM public.trip_stops WHERE id=p_stop AND trip_id=p_trip AND archived_at IS NULL FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Stop does not belong to this active trip.' USING ERRCODE='23514'; END IF;
 END IF;
 IF actor_role='TRUCKER' THEN
  IF upper(btrim(coalesce(trip_status,''))) IN ('COMPLETED','CANCELLED','CANCELED','CLOSED','FINISHED','ARCHIVED','REJECTED') THEN
   RAISE EXCEPTION 'Trucker trip is no longer active.' USING ERRCODE='42501';
  END IF;
  PERFORM a.id FROM public.trip_truck_assignments a JOIN public.drivers d ON d.id=a.driver_id
   WHERE a.trip_id=p_trip AND a.unassigned_at IS NULL AND d.profile_id=p_actor FOR SHARE OF a,d;
  IF NOT FOUND THEN RAISE EXCEPTION 'Trucker is not actively assigned.' USING ERRCODE='42501'; END IF;
 END IF;
END $function$
CREATE OR REPLACE FUNCTION public.validate_transaction_cleanup_objects_v1(p_operation_id uuid, p_actor_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE job public.transaction_deletion_jobs; object jsonb; stored storage.objects; safe jsonb:='[]';
BEGIN
 IF NOT EXISTS(SELECT FROM public.profiles WHERE id=p_actor_id AND role IN ('ADMIN','STAFF')) THEN
  RAISE EXCEPTION 'Management authorization required.' USING ERRCODE='42501'; END IF;
 SELECT * INTO STRICT job FROM public.transaction_deletion_jobs WHERE id=p_operation_id;
 FOR object IN SELECT * FROM jsonb_array_elements(job.storage_objects) LOOP
  IF object->>'bucket' NOT IN ('trip-images','report-receipts') OR object->>'bucket' IS NULL
   OR object->>'path' IS NULL OR object->>'object_id' IS NULL OR object->>'metadata_fingerprint' IS NULL THEN
   RAISE EXCEPTION 'Cleanup manifest requires object identity/ownership review.' USING ERRCODE='55000'; END IF;
  IF EXISTS(SELECT FROM public.trip_images WHERE storage_path=object->>'path')
   OR EXISTS(SELECT FROM public.report_receipts WHERE storage_path=object->>'path')
   OR EXISTS(SELECT FROM public.driver_trip_updates WHERE position(object->>'path' in coalesce(pod_image_path,''))>0 OR position(object->>'path' in coalesce(pod_image_url,''))>0)
   OR EXISTS(SELECT FROM public.driver_trip_updates WHERE nullif(btrim(pod_image_url),'') IS NOT NULL)
   OR EXISTS(SELECT FROM public.documents WHERE position('%' in coalesce(file_path,''))>0)
   OR EXISTS(SELECT FROM public.pod_drive_files WHERE position('%' in coalesce(drive_link,''))>0)
   OR EXISTS(SELECT FROM public.documents WHERE position(object->>'path' in coalesce(file_path,''))>0)
   OR EXISTS(SELECT FROM public.pod_drive_files WHERE position(object->>'path' in coalesce(drive_link,''))>0) THEN
   RAISE EXCEPTION 'Cleanup object is referenced by retained data.' USING ERRCODE='55000'; END IF;
  SELECT * INTO stored FROM storage.objects WHERE bucket_id=object->>'bucket' AND name=object->>'path';
  IF FOUND THEN
   IF stored.id::text<>object->>'object_id' OR md5(coalesce(stored.metadata::text,'')) IS DISTINCT FROM object->>'metadata_fingerprint' OR (to_jsonb(stored)->>'version') IS DISTINCT FROM object->>'object_version' THEN
    RAISE EXCEPTION 'Storage object identity changed; cleanup is blocked.' USING ERRCODE='55000'; END IF;
   safe:=safe||jsonb_build_array(object);
  END IF; -- Already-removed objects make retries idempotent.
 END LOOP;
 RETURN safe;
END $function$
CREATE OR REPLACE FUNCTION public.guard_deleted_trip_attachment_reference_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE record jsonb:=to_jsonb(NEW); object jsonb;
BEGIN
 FOR object IN SELECT value FROM public.transaction_deletion_jobs j CROSS JOIN LATERAL jsonb_array_elements(j.storage_objects) WHERE jsonb_array_length(j.storage_objects)>0 LOOP
  IF nullif(btrim(record->>'pod_image_url'),'') IS NOT NULL
   OR position('%' in coalesce(record->>'file_path',''))>0
   OR position('%' in coalesce(record->>'drive_link',''))>0
   OR record->>'storage_path'=object->>'path'
   OR position(object->>'path' in coalesce(record->>'pod_image_path',''))>0
   OR position(object->>'path' in coalesce(record->>'pod_image_url',''))>0
   OR position(object->>'path' in coalesce(record->>'file_path',''))>0
   OR position(object->>'path' in coalesce(record->>'drive_link',''))>0 THEN
   RAISE EXCEPTION 'Attachment belongs to a committed deletion journal and cannot be reused.' USING ERRCODE='55000';
  END IF;
 END LOOP;
 RETURN NEW;
END $function$
